//#region 🔖️ArtifactAssembly
/// 🧷️ One process-wide guard for a plugin's all-registry publication phase.
pub struct ArtifactAssemblyTransaction {
    _guard: MutexGuard<'static, ()>,
}

/// 🚫️ The all-registry publication barrier is unavailable after a writer panic.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ArtifactAssemblyTransactionError {
    Unavailable,
}

impl std::fmt::Display for ArtifactAssemblyTransactionError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("artifact assembly transaction unavailable")
    }
}

impl std::error::Error for ArtifactAssemblyTransactionError {}

fn artifact_assembly_lock() -> &'static Mutex<()> {
    static LOCK: std::sync::OnceLock<Mutex<()>> = std::sync::OnceLock::new();
    LOCK.get_or_init(|| Mutex::new(()))
}

/// 🧷️ Begins the only cross-registry transaction accepted by artifact registration APIs.
#[must_use]
pub fn begin_artifact_assembly() -> Result<ArtifactAssemblyTransaction, ArtifactAssemblyTransactionError> {
    Ok(ArtifactAssemblyTransaction { _guard: artifact_assembly_lock().lock().map_err(|_| ArtifactAssemblyTransactionError::Unavailable)? })
}
//#endregion 🔖️ArtifactAssembly

//#region 🔖️Schemas
/// @emoji 🔗️ Identifies the channel a document synchronizes through, when one is attached.
/// 🌱️ `Serialize`/`Deserialize` dropped outright (not even `cfg_attr(test, …)`): no production
/// consumer (`🖥️host/🦀️.rs`'s `BackboneDocument`, `🔌️plugin/🦀️.rs`'s `backbone_ref()`) requires
/// `ArtifactBackboneRef: Serialize`, and no test in this crate uses `serde_json` as a differential
/// oracle on it — confirmed by repo-wide grep before removing the derive.
#[derive(Clone, Debug, PartialEq, Eq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct ArtifactBackboneRef {
    pub uri: String,
}

/// @emoji 🔗️ Builds a backbone reference from a channel URI.
pub async fn document_backbone_ref(uri: &str) -> ArtifactBackboneRef {
    ArtifactBackboneRef { uri: uri.to_string() }
}

/// @emoji 🎯️ Undo/redo/checkout position — the store-facing twin of `crate::os_spr::HistoryCursor`.
/// Carries the FULL applied-edit list (not just the tail edit id): an edit undone mid-history
/// precedes later-applied edits in file order, and the redo stack can contain edits in any order
/// relative to `applied_edit_ids` — a single marker id cannot represent that. `checkpoint_id`
/// mirrors `ArtifactStore::current_checkpoint_id`.
/// 🌱️ `serde` is TEST-ONLY (RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS, 26/09/01):
/// `BackboneDocument` in `💻️os/🖥️host` — the only production consumer that forced `ArtifactCursor`/
/// `ArtifactCursorOwners` to stay dual — moved to a hand-written `ToValue`/`FromValue` impl (see
/// `📓️os-kernel-serde-final.md`). Production already routes through `ToValue`/`FromValue`; this
/// wave's own test fixtures (`serde_json::from_value` oracle comparisons below) still need the
/// derive, hence `cfg_attr(test, …)` rather than deleting it outright.
#[derive(Clone, Debug, Default, PartialEq, ToValue, FromValue)]
#[cfg_attr(test, derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(test, serde(rename_all = "camelCase"))]
#[value(rename_all = "camelCase")]
pub struct ArtifactCursorOwners {
    #[value(default, skip_serializing_if = "Vec::is_empty")]
    #[cfg_attr(test, serde(default, skip_serializing_if = "Vec::is_empty"))]
    pub applied_edit_ids: Vec<String>,
    #[value(default, skip_serializing_if = "Vec::is_empty")]
    #[cfg_attr(test, serde(default, skip_serializing_if = "Vec::is_empty"))]
    pub redo_edit_ids: Vec<String>,
    #[value(default, skip_serializing_if = "Option::is_none")]
    #[cfg_attr(test, serde(default, skip_serializing_if = "Option::is_none"))]
    pub checkpoint_id: Option<String>,
}

/// 🧭 Read-visible cursor root; prepared group owners stay private until their shared decision.
pub struct ArtifactCursor {
    owners: std::mem::ManuallyDrop<ArtifactCursorOwners>,
    group: std::mem::ManuallyDrop<Option<ArtifactCursorGroupRoot>>,
}

struct ArtifactCursorGroupRoot {
    visibility: Arc<crate::os_vcs::ArtifactGroupVisibility>,
    owners: ArtifactCursorOwners,
}

impl ArtifactCursor {
    pub fn new(applied_edit_ids: Vec<String>, redo_edit_ids: Vec<String>, checkpoint_id: Option<String>) -> Self {
        Self::from_owners(ArtifactCursorOwners { applied_edit_ids, redo_edit_ids, checkpoint_id })
    }

    pub fn from_owners(owners: ArtifactCursorOwners) -> Self {
        Self { owners: std::mem::ManuallyDrop::new(owners), group: std::mem::ManuallyDrop::new(None) }
    }

    pub(crate) fn stage_group_owned(&mut self, owners: ArtifactCursorOwners, visibility: &Arc<crate::os_vcs::ArtifactGroupVisibility>) -> Result<(), ArtifactCursorOwners> {
        if self.group.is_some() || !visibility.pending() {
            return Err(owners);
        }
        *self.group = Some(ArtifactCursorGroupRoot { visibility: Arc::clone(visibility), owners });
        Ok(())
    }

    pub(crate) fn adopt_group_owned(&mut self, visibility: &Arc<crate::os_vcs::ArtifactGroupVisibility>) -> Result<ArtifactCursorOwners, ()> {
        if !visibility.committed() || !self.group.as_ref().is_some_and(|group| Arc::ptr_eq(&group.visibility, visibility)) {
            return Err(());
        }
        let group = self.group.take().expect("validated committed cursor root remains owned");
        Ok(std::mem::replace(&mut *self.owners, group.owners))
    }

    pub(crate) fn abort_group_owned(&mut self, visibility: &Arc<crate::os_vcs::ArtifactGroupVisibility>) -> Result<ArtifactCursorOwners, ()> {
        if visibility.pending() || visibility.committed() || !self.group.as_ref().is_some_and(|group| Arc::ptr_eq(&group.visibility, visibility)) {
            return Err(());
        }
        Ok(self.group.take().expect("validated aborted cursor root remains owned").owners)
    }

    fn group_visibility(&self) -> Option<&crate::os_vcs::ArtifactGroupVisibility> {
        self.group.as_ref().map(|group| group.visibility.as_ref())
    }

    fn read_group(&self, decision: Option<&crate::os_vcs::ArtifactGroupReadDecision<'_>>) -> Result<&ArtifactCursorOwners, ()> {
        match self.group.as_ref() {
            Some(group) if decision.ok_or(())?.committed_for(&group.visibility)? => Ok(&group.owners),
            _ => Ok(&*self.owners),
        }
    }
}

impl Default for ArtifactCursor {
    fn default() -> Self {
        Self::from_owners(ArtifactCursorOwners::default())
    }
}

impl std::ops::Deref for ArtifactCursor {
    type Target = ArtifactCursorOwners;

    fn deref(&self) -> &Self::Target {
        self.group.as_ref().filter(|group| group.visibility.committed()).map_or(&*self.owners, |group| &group.owners)
    }
}

impl std::ops::DerefMut for ArtifactCursor {
    fn deref_mut(&mut self) -> &mut Self::Target {
        assert!(self.group.is_none(), "mutable cursor access requires its staged group to be adopted or aborted");
        &mut self.owners
    }
}

impl Clone for ArtifactCursor {
    fn clone(&self) -> Self {
        Self::from_owners((**self).clone())
    }
}

impl std::fmt::Debug for ArtifactCursor {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        (**self).fmt(formatter)
    }
}

impl PartialEq for ArtifactCursor {
    fn eq(&self, other: &Self) -> bool {
        **self == **other
    }
}

impl ToValue for ArtifactCursor {
    fn to_value(&self) -> DslValue {
        (**self).to_value()
    }
}

impl FromValue for ArtifactCursor {
    fn from_value(value: DslValue) -> Result<Self, ValueError> {
        Ok(Self::from_owners(ArtifactCursorOwners::from_value(value)?))
    }
}

/// 🌉️ serde twin of the `ToValue`/`FromValue` pair above — TEST-ONLY
/// (RUNTIME-DEPENDENCY-ELIMINATION-FOR-S-PLUGINS-AND-ARTIFACTS, 26/09/01): `BackboneDocument` in
/// `💻️os/🖥️host`, the only production consumer that forced this to stay unconditional, moved to a
/// hand-written `ToValue`/`FromValue` impl (see `📓️os-kernel-serde-final.md`). Delegates through
/// the same `ArtifactCursorOwners` view (itself now also `cfg_attr(test, …)`-gated) so both
/// encodings emit an identical shape. Hand-written rather than derived because the private fields
/// are `ManuallyDrop` (the staged group root must be adopted or retired before `Drop`), which no
/// derive can see through.
#[cfg(test)]
impl Serialize for ArtifactCursor {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        Serialize::serialize(&**self, serializer)
    }
}

/// 🌉️ Mirror of the `Serialize` twin directly above — also test-only.
#[cfg(test)]
impl<'de> Deserialize<'de> for ArtifactCursor {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        ArtifactCursorOwners::deserialize(deserializer).map(Self::from_owners)
    }
}

impl Drop for ArtifactCursor {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.group.is_none()), "artifact cursor reached Drop before its exact staged root was adopted or returned for retirement");
        unsafe { std::mem::ManuallyDrop::drop(&mut self.owners) };
    }
}

//#region 🔖️HistoryLane
/// @emoji 🛤️ Which undo/redo cursor a recorded edit belongs to. `Document` is the default — the
/// ordinary main history `Undo`/`Redo` travels. Any other lane (starting with `Interaction`) is a
/// persisted, replayable SIDE history: mutations recorded under it stay in `ArtifactVcs.edits` and
/// `ArtifactEnvelope.lanes` forever (never dropped, never un-persisted), but default `Undo`/`Redo`
/// skip past them to the nearest `Document`-lane entry instead of reverting them — see
/// `ArtifactStore::dispatch`'s `Undo`/`Redo` arms, and `ArtifactCommand::UndoInLane`/`RedoInLane`
/// for the explicit lane-scoped API that CAN walk a non-`Document` lane. Deliberately an
/// extensible general store mechanism — e.g. a future framework-owned selection/interaction state
/// that must survive reload but must never be what a document editor's undo reverts — not a
/// hover/selection special case baked into this crate. See ticket
/// `26/08/14/FIRST-CLASS-HOVER-AND-SELECTION-MECHANISM/📋️master.md` decision 1.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub enum HistoryLane {
    #[default]
    Document,
    Interaction,
}

impl HistoryLane {
    async fn is_document(&self) -> bool {
        matches!(self, HistoryLane::Document)
    }
}
//#endregion 🔖️HistoryLane

#[derive(Debug, PartialEq)]
pub struct ArtifactEnvelopeOwners<P, Mutation> {
    pub schema: String,
    pub id: String,
    pub vcs: ArtifactVcs<P, Mutation>,
    pub backbone: Option<ArtifactBackboneRef>,
    pub active_alternative_id: Option<String>,
    /// @emoji 🎯️ Undo/redo/checkout position, present only once a store has synced it (see
    /// `ArtifactStore::sync_cursor`) — absent for a freshly-constructed envelope or one loaded
    /// from a source that predates this field, in which case position stays runtime-only exactly
    /// as before.
    pub cursor: Option<ArtifactCursor>,
    /// @emoji 🗣️ The dialect this envelope's `vcs.initial_snapshot` (and every replayed edit) is
    /// currently in — absent for envelopes minted before dialect-tracking existed, or for document
    /// kinds that never adopted more than one dialect. See `26/08/10` D4 evolution slice; nothing
    /// in `ArtifactStore::dispatch` reads or writes this yet (that wiring is later scope) — it is
    /// purely a persisted fact a future migration-aware caller can act on.
    pub dialect: Option<crate::os_io::ArtifactDialect>,
    /// @emoji 🧬️ Set once, the first time this envelope's snapshot was produced by migrating a
    /// prior document's dialect (see `migrate_document` below) rather than being authored directly
    /// in `dialect`. Absent for every envelope that was never migrated.
    pub migrated_from: Option<MigrationProvenance>,
    /// @emoji 🏠️ Present exactly when this envelope is a CHILD in a composition — the ownership
    /// stamp naming which parent/slot/`child_id` created it (see `🔖️Composition` below). Placed on
    /// the CHILD's own envelope (not only on the parent's `ArtifactChild` handle) so ownership is
    /// queryable directly from the child side — e.g. "is this document embeddable standalone, or
    /// does deleting it require going through its owner". Absent for every independent artifact
    /// (the overwhelming majority) and for every envelope minted before this ticket.
    pub owner: Option<OwnerRef>,
    /// @emoji 🛤️ Sparse `Edit.id → HistoryLane` ledger: only entries recorded under a NON-`Document`
    /// lane are ever inserted (an ordinary document edit never gets a map entry at all), so an id
    /// absent from this map is `HistoryLane::Document` by construction — see
    /// `ArtifactStore::edit_lane`. Additive — absent (empty map) for every envelope minted before
    /// this field existed, all of which therefore decode as if every edit were `Document` lane,
    /// matching prior undo/redo behavior exactly. Lives on the envelope (not on `Edit<Mutation>`
    /// itself, which this crate's per-technology `Mutation` types don't own) so it survives a plain
    /// JSON round trip (`ArtifactStore::envelope_json`) alongside `cursor`/`owner`/`dialect`.
    pub lanes: BTreeMap<String, HistoryLane>,
    pub edit_messages: ArtifactEditMessageLedger,
    pub conflicts: Vec<crate::os_spr::Conflict>,
}

/// 📸️ One immutable envelope observation; cursor and every history ledger share one captured decision.
pub struct ArtifactEnvelopeRead<'a, P, Mutation> {
    schema: &'a str,
    id: &'a str,
    vcs: crate::os_vcs::ArtifactVcsRead<'a, P, Mutation>,
    backbone: Option<&'a ArtifactBackboneRef>,
    active_alternative_id: Option<&'a String>,
    cursor: Option<&'a ArtifactCursorOwners>,
    dialect: Option<&'a crate::os_io::ArtifactDialect>,
    migrated_from: Option<&'a MigrationProvenance>,
    owner: Option<&'a OwnerRef>,
    lanes: &'a BTreeMap<String, HistoryLane>,
    edit_messages: &'a ArtifactEditMessageLedger,
    conflicts: &'a Vec<crate::os_spr::Conflict>,
}

/// 🌉️ Hand-written, not derived: every field but `vcs` is a plain reference or `Option<&T>`, and
/// no blanket `impl<T: ToValue> ToValue for &T` exists in this codebase (see `ArtifactVcsRead`'s
/// own docstring) — mirrors the former `#[derive(Serialize)]`'s `skip_serializing_if` shape by
/// simply omitting the key when the option is `None`/the map is empty.
impl<P: ToValue, Mutation: ToValue> ToValue for ArtifactEnvelopeRead<'_, P, Mutation> {
    fn to_value(&self) -> DslValue {
        let mut entries = vec![("schema".to_string(), self.schema.to_value()), ("id".to_string(), self.id.to_value()), ("vcs".to_string(), self.vcs.to_value())];
        if let Some(backbone) = self.backbone {
            entries.push(("backbone".to_string(), backbone.to_value()));
        }
        if let Some(active_alternative_id) = self.active_alternative_id {
            entries.push(("activeAlternativeId".to_string(), active_alternative_id.to_value()));
        }
        if let Some(cursor) = self.cursor {
            entries.push(("cursor".to_string(), cursor.to_value()));
        }
        if let Some(dialect) = self.dialect {
            entries.push(("dialect".to_string(), dialect.to_value()));
        }
        if let Some(migrated_from) = self.migrated_from {
            entries.push(("migratedFrom".to_string(), migrated_from.to_value()));
        }
        if let Some(owner) = self.owner {
            entries.push(("owner".to_string(), owner.to_value()));
        }
        if !self.lanes.is_empty() {
            entries.push(("lanes".to_string(), self.lanes.to_value()));
        }
        entries.push(("editMessages".to_string(), self.edit_messages.to_value()));
        entries.push(("conflicts".to_string(), self.conflicts.to_value()));
        DslValue::Object(entries)
    }
}

impl<P, Mutation> ArtifactEnvelopeOwners<P, Mutation> {
    /// 📸️ Captures read roots before any serializer can cross a shared group decision.
    pub fn capture_read(&self) -> Result<ArtifactEnvelopeRead<'_, P, Mutation>, &'static str> {
        let history_visibility = self.vcs.group_visibility().map_err(|()| "envelope history contains different group authorities")?;
        let cursor_visibility = self.cursor.as_ref().and_then(ArtifactCursor::group_visibility);
        if history_visibility.zip(cursor_visibility).is_some_and(|(history, cursor)| !std::ptr::eq(history, cursor)) {
            return Err("envelope cursor and history have different group authorities");
        }
        let decision = history_visibility.or(cursor_visibility).map(crate::os_vcs::ArtifactGroupVisibility::capture);
        let vcs = self.vcs.read_group(decision.as_ref()).map_err(|()| "envelope history lost its captured group authority")?;
        let cursor = self.cursor.as_ref().map(|cursor| cursor.read_group(decision.as_ref())).transpose().map_err(|()| "envelope cursor lost its captured group authority")?;
        Ok(ArtifactEnvelopeRead {
            schema: &self.schema,
            id: &self.id,
            vcs,
            backbone: self.backbone.as_ref(),
            active_alternative_id: self.active_alternative_id.as_ref(),
            cursor,
            dialect: self.dialect.as_ref(),
            migrated_from: self.migrated_from.as_ref(),
            owner: self.owner.as_ref(),
            lanes: &self.lanes,
            edit_messages: &self.edit_messages,
            conflicts: &self.conflicts,
        })
    }
}

/// @emoji 🛡️ Terminal shell for one exact document record. Deep fields are ManuallyDrop from
/// birth and can leave the shell only through the bounded store/completed-record owner protocols.
pub struct ArtifactEnvelope<P, Mutation> {
    owners: std::mem::ManuallyDrop<ArtifactEnvelopeOwners<P, Mutation>>,
    owners_detached: bool,
}

impl<P, Mutation> ArtifactEnvelope<P, Mutation> {
    pub fn from_owners(owners: ArtifactEnvelopeOwners<P, Mutation>) -> Self {
        Self { owners: std::mem::ManuallyDrop::new(owners), owners_detached: false }
    }

    /// @emoji 🧺️ Consumes the terminal shell and hands back its owners. This is the ONLY way a caller
    /// outside this module can read an envelope's fields: the shell's `Drop` asserts that its owners
    /// were detached first, so reading fields by reference and letting the shell fall out of scope
    /// aborts at runtime ("terminal shell reached Drop before ... detached every nested owner").
    /// `🖥️host`'s `BackboneDocument` construction goes through here for exactly that reason.
    pub fn into_owners(mut self) -> ArtifactEnvelopeOwners<P, Mutation> {
        assert!(!self.owners_detached, "artifact envelope owners were detached twice");
        self.owners_detached = true;
        unsafe { std::mem::ManuallyDrop::take(&mut self.owners) }
    }

    /// @emoji 🌱️ Moves the sole snapshot from a decoder-proven fresh envelope. Rejection
    /// returns the exact shell untouched; accepted metadata is definitionally bounded and empty.
    pub fn try_into_fresh_snapshot(self) -> Result<P, Self> {
        if self.schema.len() > 256
            || self.id.len() > 256
            || !self.vcs.edits.is_empty()
            || !self.vcs.changes.is_empty()
            || !self.vcs.checkpoints.is_empty()
            || !self.vcs.alternatives.is_empty()
            || self.backbone.is_some()
            || self.active_alternative_id.is_some()
            || self.cursor.is_some()
            || self.dialect.is_some()
            || self.migrated_from.is_some()
            || self.owner.is_some()
            || !self.lanes.is_empty()
            || !self.edit_messages.is_empty()
            || !self.conflicts.is_empty()
        {
            return Err(self);
        }
        let ArtifactEnvelopeOwners { schema, id, vcs, backbone, active_alternative_id, cursor, dialect, migrated_from, owner, lanes, edit_messages, conflicts } = self.into_owners();
        let ArtifactVcs { initial_snapshot, edits, changes, checkpoints, alternatives } = vcs;
        drop((schema, id, edits, changes, checkpoints, alternatives, backbone, active_alternative_id, cursor, dialect, migrated_from, owner, lanes, edit_messages, conflicts));
        Ok(initial_snapshot)
    }
}

impl<P, Mutation> std::ops::Deref for ArtifactEnvelope<P, Mutation> {
    type Target = ArtifactEnvelopeOwners<P, Mutation>;

    fn deref(&self) -> &Self::Target {
        &self.owners
    }
}

impl<P, Mutation> std::ops::DerefMut for ArtifactEnvelope<P, Mutation> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.owners
    }
}

impl<P: std::fmt::Debug, Mutation: std::fmt::Debug> std::fmt::Debug for ArtifactEnvelope<P, Mutation> {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        self.owners.fmt(formatter)
    }
}

impl<P: PartialEq, Mutation: PartialEq> PartialEq for ArtifactEnvelope<P, Mutation> {
    fn eq(&self, other: &Self) -> bool {
        self.owners.eq(&other.owners)
    }
}

impl<P, Mutation> Drop for ArtifactEnvelope<P, Mutation> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.owners_detached), "artifact envelope terminal shell reached Drop before its app-owned bounded retirement authority detached every nested owner");
    }
}

/// @emoji 🧬️ Provenance stamp for an envelope produced by `migrate_document`: which prior document,
/// which dialect it was in, and (if the migration ran at a specific checkpoint rather than the
/// live tip) which checkpoint. `migrated_at` follows this crate's existing `Checkpoint.timestamp`/
/// `Edit.started_at` convention (a caller-supplied string stamped via `now_iso()`, see below) — no
/// new clock abstraction introduced for this one field.
#[derive(Clone, Debug, PartialEq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct MigrationProvenance {
    pub document_id: String,
    pub dialect: crate::os_io::ArtifactDialect,
    #[value(default, skip_serializing_if = "Option::is_none")]
    pub checkpoint_id: Option<String>,
    pub migrated_at: String,
}

#[derive(Clone, Debug, PartialEq, ToValue, FromValue)]
#[value(tag = "kind", rename_all = "camelCase")]
pub enum ArtifactCommand<Mutation> {
    Apply {
        mutations: Vec<Mutation>,
        #[value(skip_serializing_if = "Option::is_none")]
        description: Option<String>,
    },
    Undo,
    Redo,
    UndoWithPolicy {
        policy: UndoPolicy,
        #[value(default, skip_serializing_if = "Option::is_none")]
        semantic_command: Option<Box<ArtifactCommand<Mutation>>>,
    },
    /// @emoji 🛤️ `Apply`'s lane-tagged twin — records the resulting edit under `lane` (via
    /// `ArtifactEnvelope.lanes`) instead of the implicit `HistoryLane::Document` a plain `Apply`
    /// gets. New variant, not a field added to `Apply` itself, so every existing `Apply {
    /// mutations, description }` construction across the workspace keeps compiling untouched.
    ApplyInLane {
        mutations: Vec<Mutation>,
        #[value(skip_serializing_if = "Option::is_none")]
        description: Option<String>,
        #[value(default)]
        lane: HistoryLane,
    },
    /// @emoji 🛤️ `AmendLast`'s lane-tagged twin — see `ApplyInLane`'s doc for why this is an
    /// additive new variant rather than a field on `AmendLast`.
    AmendLastInLane {
        mutations: Vec<Mutation>,
        coalesce_key: Option<String>,
        #[value(default)]
        lane: HistoryLane,
    },
    /// @emoji 🛤️ Explicit lane-scoped undo: mirrors plain `Undo`'s `ExactBaseOnly` semantics (must
    /// be local, must be the nearest-to-tail match) but searches `applied_edit_ids` for the nearest
    /// entry whose `HistoryLane` is exactly `lane`, instead of `HistoryLane::Document`. Lets a
    /// caller walk a non-`Document` lane on purpose — the completing half of "default `Undo`/`Redo`
    /// skip non-`Document` lanes" (see `ArtifactStore::dispatch`'s `Undo` arm).
    UndoInLane {
        lane: HistoryLane,
    },
    /// @emoji 🛤️ `UndoInLane`'s redo-direction sibling — mirrors plain `Redo`, but pops the
    /// nearest-to-top `redo_edit_ids` entry whose `HistoryLane` is exactly `lane`.
    RedoInLane {
        lane: HistoryLane,
    },
    CommitCheckpoint {
        #[value(skip_serializing_if = "Option::is_none")]
        message: Option<String>,
        #[value(default, skip_serializing_if = "Vec::is_empty")]
        authors: Vec<Author>,
    },
    CreateAlternative {
        name: String,
    },
    SwitchAlternative {
        alternative_id: String,
    },
    CheckoutCheckpoint {
        #[value(rename = "checkpointId")]
        checkpoint_id: String,
    },
    AmendLast {
        mutations: Vec<Mutation>,
        /// @emoji 🪢️ Matches the last uncommitted edit's `coalesce_key` to absorb into it instead of creating a new edit.
        coalesce_key: Option<String>,
    },
    /// @emoji 🕸️ Feeds a remote MutationEnvelope through the causal DAG into the edit timeline.
    IngestRemote {
        #[value(serialize_with = "operation_envelope_serde::to_value", deserialize_with = "operation_envelope_serde::from_value")]
        envelope: crate::os_spr::MutationEnvelope,
    },
    /// @emoji 🧹 Clears volatile draft-lane history that must never enter a Change/Checkpoint.
    PruneDrafts,
    /// @emoji ⚖️ Sets this store's local `crate::os_spr::MergePolicy` — authority-local state, never
    /// carried on a `crate::os_spr::MutationEnvelope`/`BackboneMessage`, never part of shared
    /// history (`26/08/16/MUTATION-OUTCOMES-MERGE-POLICIES-AND-FIRST-CLASS-CONFLICTS` §C6). Ordinal
    /// 15 — frozen, appended after `PruneDrafts`.
    SetMergePolicy {
        policy: crate::os_spr::MergePolicy,
    },
    /// @emoji ⚔️ Resolves an `Open` `crate::os_spr::Conflict` by id — see
    /// `ArtifactStore::resolve_conflict` for what `Accept`/`Discard` do for each conflict kind.
    /// Ordinal 16 — frozen.
    ResolveConflict {
        conflict_id: String,
        resolution: crate::os_spr::ConflictResolution,
    },
}

impl<Mutation> ArtifactCommand<Mutation> {
    /// 🔮️ Names the projection-invalidating transition this command performs, if it has one.
    pub async fn projection_cause(&self) -> Option<ArtifactProjectionCause> {
        match self {
            Self::Apply { .. } | Self::ApplyInLane { .. } | Self::AmendLast { .. } | Self::AmendLastInLane { .. } => Some(ArtifactProjectionCause::Apply),
            Self::IngestRemote { .. } => Some(ArtifactProjectionCause::RemoteIngest),
            Self::Undo | Self::UndoWithPolicy { .. } | Self::UndoInLane { .. } => Some(ArtifactProjectionCause::Undo),
            Self::Redo | Self::RedoInLane { .. } => Some(ArtifactProjectionCause::Redo),
            Self::CheckoutCheckpoint { .. } | Self::CreateAlternative { .. } | Self::SwitchAlternative { .. } => Some(ArtifactProjectionCause::Checkout),
            Self::CommitCheckpoint { .. } => Some(ArtifactProjectionCause::Checkpoint),
            Self::PruneDrafts => Some(ArtifactProjectionCause::PruneDrafts),
            Self::SetMergePolicy { .. } => Some(ArtifactProjectionCause::PolicyChange),
            Self::ResolveConflict { .. } => Some(ArtifactProjectionCause::RemoteIngest),
        }
    }
}
//#endregion 🔖️Schemas

//#region 🔖️Composition
// 🧩️ Composable-vs-referenceable artifact primitives (ticket `26/08/12/UNIFIED-COMPOSABLE-
// ARTIFACT-SYSTEM` `📓️design-full-plan.md` §"1. Kernel primitives"). Two structurally distinct
// relationships between artifacts:
// - a **CHILD** (`ArtifactChild<S>` on the parent's snapshot / `OwnerRef` on the child's own
//   envelope): the parent creates and deletes it, it has exactly one owner, no pin, no
//   independent lifecycle, and nests inline in UI — but it is still its OWN `ArtifactEnvelope`
//   with its own `ArtifactVcs` history and store, never an inline subtree (this crate's own doc
//   comment / the design doc's "Child = own envelope" decision). Consequently a parent's diff
//   NEVER embeds a child diff.
// - a **LINK** (`ArtifactLink`/`LinkPin`): an independent lifecycle of its own, a PIN (so it can
//   be frozen to a specific `Head`/`Checkpoint`/content-addressed `Snapshot`), and renders as a
//   chip, never nested inline.
//
// `ArtifactRefs` lets a snapshot type declare its own children/links (defaulted to none, so a
// leaf artifact needs zero boilerplate); `LinkResolver`/`ChildStoreFactory` are the host-side
// seams that turn those declarations into real bytes/stores. `CompositionCoordinator` (its own
// `🔖️CompositionCoordinator` region, after `🔖️Space` below) orchestrates atomic multi-store
// dispatch across a parent and its children on top of these types.

/// @emoji 🧸️ Ownership handle a parent SNAPSHOT embeds for one owned child slot (e.g. a plugin's
/// generated field `mesh_child: ArtifactChild<MeshSnapshot>`). `S` is a compile-time-only phantom
/// naming which snapshot type the child is expected to materialize as — it never appears on the
/// wire and never constrains this type's own capabilities. `Clone`/`Debug`/`PartialEq` are
/// hand-implemented below (not `#[derive(..)]`'d): deriving them on a `PhantomData<S>`-carrying
/// struct adds an unwanted `S: Trait` bound to every impl even though `S` never appears in any
/// stored/compared data, so those three derives would silently fail to work "for any `S`" (the
/// task's own requirement) the moment a caller picked an `S` that itself didn't implement
/// `Clone`/`Debug`/`PartialEq`. `Serialize`/`Deserialize` avoid the same trap via `#[serde(bound =
/// "")]` instead of a hand impl — the standard serde idiom for a `PhantomData<S>` field, since
/// serde's derive macro honors an explicit empty bound list rather than inferring one from `S`.
/// `local_owner` is a serialization-skipped, immutable materialization retained by this exact
/// handle; it is intentionally absent from equality, debug, DSL, pack, and JSON identity. No pin,
/// no independent lifecycle: see the region doc's CHILD-vs-LINK split.
struct ArtifactChildLocalText(Arc<str>);

/// @emoji 🚫️ Why an owned child's local materialization cannot be read at a typed boundary.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArtifactChildMaterializationError {
    Absent,
    WrongType,
}

impl std::fmt::Display for ArtifactChildMaterializationError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Absent => formatter.write_str("artifact child is not materialized"),
            Self::WrongType => formatter.write_str("artifact child materialization has a different exact type"),
        }
    }
}

impl std::error::Error for ArtifactChildMaterializationError {}

pub struct ArtifactChild<S> {
    pub child_id: String,
    pub target: crate::os_io::ArtifactRef,
    local_owner: Option<Arc<dyn std::any::Any + Send + Sync>>,
    _snapshot: PhantomData<S>,
}

impl<S> ArtifactChild<S> {
    /// 🏗️ Constructs a handle, threading the phantom marker for the caller.
    pub fn new(child_id: String, target: crate::os_io::ArtifactRef) -> Self {
        Self { child_id, target, local_owner: None, _snapshot: PhantomData }
    }

    /// 🪆 Attaches an immutable local-only materialization to this owned child handle.
    pub fn with_local_owner<T: std::any::Any + Send + Sync>(mut self, owner: Arc<T>) -> Self {
        self.local_owner = Some(owner);
        self
    }

    /// 🪆 Replaces this handle's immutable local-only materialization owner.
    pub fn set_local_owner<T: std::any::Any + Send + Sync>(&mut self, owner: Arc<T>) {
        self.local_owner = Some(owner);
    }

    /// 🧵 Retains a type-checked local-only materialization without cloning its payload.
    pub fn local_owner<T: std::any::Any + Send + Sync>(&self) -> Option<Arc<T>> {
        Arc::downcast::<T>(self.local_owner.clone()?).ok()
    }

    /// 📤️ Requires the exact local materialization at content-reading boundaries. Exporters must
    /// propagate this failure instead of serializing the handle or substituting default content.
    pub fn require_local_owner<T: std::any::Any + Send + Sync>(&self) -> Result<Arc<T>, ArtifactChildMaterializationError> {
        let owner = self.local_owner.clone().ok_or(ArtifactChildMaterializationError::Absent)?;
        Arc::downcast::<T>(owner).map_err(|_| ArtifactChildMaterializationError::WrongType)
    }

    /// 📤️ Transfers the exact typed local owner; a type mismatch retains the untouched owner.
    pub fn take_local_owner<T: std::any::Any + Send + Sync>(&mut self) -> Result<Option<Arc<T>>, &'static str> {
        let Some(owner) = self.local_owner.take() else {
            return Ok(None);
        };
        match Arc::downcast::<T>(owner) {
            Ok(owner) => Ok(Some(owner)),
            Err(owner) => {
                self.local_owner = Some(owner);
                Err("artifact child local owner has a different exact type")
            }
        }
    }

    /// 🪆 Attaches immutable local-only text to this owned child handle.
    pub fn with_local_text(mut self, text: Arc<str>) -> Self {
        self.local_owner = Some(Arc::new(ArtifactChildLocalText(text)));
        self
    }

    /// 🪆 Replaces this handle's immutable local-only text owner.
    pub fn set_local_text(&mut self, text: Arc<str>) {
        self.local_owner = Some(Arc::new(ArtifactChildLocalText(text)));
    }

    /// 🔎 Borrows this handle's local-only text when the child has been materialized.
    pub fn local_text(&self) -> Option<&str> {
        self.local_owner.as_deref()?.downcast_ref::<ArtifactChildLocalText>().map(|owner| owner.0.as_ref())
    }

    /// 🧵 Retains this handle's local-only text owner without copying its bytes.
    pub fn local_text_owner(&self) -> Option<Arc<str>> {
        self.local_owner.as_deref()?.downcast_ref::<ArtifactChildLocalText>().map(|owner| owner.0.clone())
    }

    /// 🪪️ Drops the compile-time-only `S` phantom, producing the type-erased projection
    /// `ArtifactRefs::child_refs` returns.
    pub async fn to_child_ref(&self, slot: &str) -> ChildRef {
        ChildRef { slot: slot.to_string(), child_id: self.child_id.clone(), target: self.target.clone() }
    }
}

impl<S> Clone for ArtifactChild<S> {
    fn clone(&self) -> Self {
        Self { child_id: self.child_id.clone(), target: self.target.clone(), local_owner: self.local_owner.clone(), _snapshot: PhantomData }
    }
}

impl<S> crate::os_schema_composition::ChildFieldRefs for ArtifactChild<S> {
    const MANY: bool = false;
    fn visit_child_field<'a, V: crate::os_schema_composition::ChildRefVisitor<'a>>(&'a self, slot: &'static str, visitor: &mut V) -> Result<(), V::Error> {
        visitor.step()?;
        visitor.child(
            slot,
            crate::os_schema_composition::ChildRefFields {
                child_id: &self.child_id,
                artifact_id: &self.target.artifact_id,
                artifact_kind: &self.target.dialect.artifact_kind,
                standard: &self.target.dialect.standard,
                subset: &self.target.dialect.subset,
            },
        )
    }
}

impl<S> std::fmt::Debug for ArtifactChild<S> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ArtifactChild").field("child_id", &self.child_id).field("target", &self.target).finish()
    }
}

impl<S> PartialEq for ArtifactChild<S> {
    fn eq(&self, other: &Self) -> bool {
        self.child_id == other.child_id && self.target == other.target
    }
}

/// 🌉️ Hand-written, not derived: `ArtifactChild<S>`'s `local_owner`/`_snapshot` fields are
/// serialization-skipped (see the struct's own doc comment), a shape `#[derive(ToValue,
/// FromValue)]` does not support — mirrors the pre-existing `#[serde(skip)]` hand-treatment,
/// round-tripping only `child_id`/`target`.
impl<S> ToValue for ArtifactChild<S> {
    fn to_value(&self) -> DslValue {
        DslValue::object([("childId".to_string(), ToValue::to_value(&self.child_id)), ("target".to_string(), ToValue::to_value(&self.target))])
    }
}

impl<S> FromValue for ArtifactChild<S> {
    fn from_value(value: DslValue) -> Result<Self, ValueError> {
        let DslValue::Object(fields) = value else {
            return Err(ValueError::new(format!("expected an object for ArtifactChild, found {value:?}")));
        };
        let mut child_id = None;
        let mut target = None;
        for (key, entry) in fields {
            match key.as_str() {
                "childId" => child_id = Some(String::from_value(entry).map_err(|e| e.under("childId"))?),
                "target" => target = Some(crate::os_io::ArtifactRef::from_value(entry).map_err(|e| e.under("target"))?),
                _ => return Err(ValueError::new(format!("ArtifactChild has unknown field {key}"))),
            }
        }
        Ok(ArtifactChild { child_id: child_id.ok_or_else(|| ValueError::new("ArtifactChild missing childId"))?, target: target.ok_or_else(|| ValueError::new("ArtifactChild missing target"))?, local_owner: None, _snapshot: PhantomData })
    }
}

/// @emoji 🪪️ Type-erased projection of one `ArtifactChild<S>` field, dropping the compile-time-only
/// `S` phantom so `ArtifactRefs::child_refs` can return a single homogeneous `Vec` across however
/// many differently-`S`-typed child slots a snapshot declares.
#[derive(Clone, Debug, PartialEq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub struct ChildRef {
    pub slot: String,
    pub child_id: String,
    pub target: crate::os_io::ArtifactRef,
}

/// 📏️ Fixed restore admission bounds; sparse container walks consume their own step budget.
pub const CHILD_RESTORE_MAXIMUM_REFERENCES: usize = 64;
pub const CHILD_RESTORE_MAXIMUM_FIELD_BYTES: usize = 256;
pub const CHILD_RESTORE_MAXIMUM_VISIT_STEPS: usize = 256;

/// 🛑️ Exact loaded-parent projection failures, before opening or publishing any child store.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ChildRestoreProjectionError {
    InvalidSlot,
    InvalidReference,
    DuplicateChild,
    SingularSlot,
    ReferenceLimit,
    TraversalLimit,
    IncompleteSet,
}

impl std::fmt::Display for ChildRestoreProjectionError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(formatter, "child restore projection: {self:?}")
    }
}

impl std::error::Error for ChildRestoreProjectionError {}

/// 🌳️ Bounded borrowed authority derived only from the loaded parent's declared child fields.
#[derive(Debug)]
pub struct ChildRestoreProjection<'a> {
    slots: &'static [crate::os_schema_composition::ChildSlotSpec],
    rows: [Option<(&'static str, crate::os_schema_composition::ChildRefFields<'a>)>; CHILD_RESTORE_MAXIMUM_REFERENCES],
    length: usize,
    steps: usize,
}

impl<'a> ChildRestoreProjection<'a> {
    /// 🔎️ Visits actual typed snapshot fields without cloning handles, leases or child content.
    pub fn from_snapshot<S: crate::os_schema_composition::ArtifactCompositionFields>(snapshot: &'a S) -> Result<Self, ChildRestoreProjectionError> {
        let slots = S::child_slots();
        if slots.len() > CHILD_RESTORE_MAXIMUM_REFERENCES {
            return Err(ChildRestoreProjectionError::ReferenceLimit);
        }
        for (index, slot) in slots.iter().enumerate() {
            if slot.name.is_empty()
                || slot.name.len() > CHILD_RESTORE_MAXIMUM_FIELD_BYTES
                || slot.kind.len() > CHILD_RESTORE_MAXIMUM_FIELD_BYTES
                || !crate::os_io::is_canonical_artifact_kind(slot.kind)
                || slots[..index].iter().any(|prior| prior.name == slot.name)
            {
                return Err(ChildRestoreProjectionError::InvalidSlot);
            }
        }
        let mut projection = Self { slots, rows: [None; CHILD_RESTORE_MAXIMUM_REFERENCES], length: 0, steps: 0 };
        snapshot.visit_child_refs(&mut projection)?;
        Ok(projection)
    }

    /// 🧮️ Number of exact child references carried by this loaded parent.
    pub fn len(&self) -> usize {
        self.length
    }

    /// 🍃️ Whether this projection has no populated child fields.
    pub fn is_empty(&self) -> bool {
        self.length == 0
    }

    /// 🌿️ Reads one admitted typed child row without copying handles or payload owners.
    pub fn get(&self, index: usize) -> Option<(&'static str, crate::os_schema_composition::ChildRefFields<'a>)> {
        self.rows.get(index).copied().flatten()
    }

    /// 🪪️ Checks one member against the actual loaded parent, without treating it as a full batch.
    pub fn admits_member(&self, slot: &str, expected: &crate::os_io::ArtifactRef) -> bool {
        self.rows[..self.length].iter().flatten().any(|(name, fields)| {
            *name == slot
                && fields.child_id == expected.artifact_id
                && fields.artifact_id == expected.artifact_id
                && fields.artifact_kind == expected.dialect.artifact_kind
                && fields.standard == expected.dialect.standard
                && fields.subset == expected.dialect.subset
        })
    }

    /// ⚖️ Admits exactly one unordered complete set: no omission, substitution or duplicate.
    pub fn admit_complete<'b>(&self, incoming: impl IntoIterator<Item = (&'b str, crate::os_schema_composition::ChildRefFields<'b>)>) -> Result<(), ChildRestoreProjectionError> {
        let mut seen = [false; CHILD_RESTORE_MAXIMUM_REFERENCES];
        let mut count = 0;
        for (slot, fields) in incoming {
            if count == CHILD_RESTORE_MAXIMUM_REFERENCES {
                return Err(ChildRestoreProjectionError::ReferenceLimit);
            }
            let index = self.rows[..self.length].iter().position(|entry| entry.as_ref().is_some_and(|(name, expected)| *name == slot && *expected == fields)).ok_or(ChildRestoreProjectionError::IncompleteSet)?;
            if seen[index] {
                return Err(ChildRestoreProjectionError::DuplicateChild);
            }
            seen[index] = true;
            count += 1;
        }
        if count != self.length {
            return Err(ChildRestoreProjectionError::IncompleteSet);
        }
        Ok(())
    }
}

impl<'a> crate::os_schema_composition::ChildRefVisitor<'a> for ChildRestoreProjection<'a> {
    type Error = ChildRestoreProjectionError;
    fn step(&mut self) -> Result<(), Self::Error> {
        if self.steps == CHILD_RESTORE_MAXIMUM_VISIT_STEPS {
            return Err(Self::Error::TraversalLimit);
        }
        self.steps += 1;
        Ok(())
    }
    fn child(&mut self, slot: &'static str, fields: crate::os_schema_composition::ChildRefFields<'a>) -> Result<(), Self::Error> {
        if self.length == CHILD_RESTORE_MAXIMUM_REFERENCES {
            return Err(Self::Error::ReferenceLimit);
        }
        let spec = self.slots.iter().find(|spec| spec.name == slot).ok_or(Self::Error::InvalidSlot)?;
        if fields.child_id != fields.artifact_id
            || fields.artifact_kind != spec.kind
            || [fields.child_id, fields.artifact_id, fields.artifact_kind, fields.standard, fields.subset].iter().any(|field| field.is_empty() || field.len() > CHILD_RESTORE_MAXIMUM_FIELD_BYTES)
        {
            return Err(Self::Error::InvalidReference);
        }
        for (name, prior) in self.rows[..self.length].iter().flatten() {
            if prior.child_id == fields.child_id {
                return Err(Self::Error::DuplicateChild);
            }
            if *name == slot && !spec.many {
                return Err(Self::Error::SingularSlot);
            }
        }
        self.rows[self.length] = Some((slot, fields));
        self.length += 1;
        Ok(())
    }
}

/// @emoji 🏠️ The ownership stamp placed on the CHILD's own `ArtifactEnvelope.owner` (not only on
/// the parent's `ArtifactChild` handle), so ownership is queryable directly from the child side —
/// e.g. "is this document embeddable standalone, or does deleting it require going through its
/// owner". `child_id` matches the owning `ArtifactChild<S>.child_id`/`ChildRef.child_id` exactly.
#[path = "🪆️child/🏠️owner/🧬️schema/🦀️.rs"]
mod artifact_child_owner_schema;
pub use artifact_child_owner_schema::OwnerRef;

#[path = "🔗️link/🧬️schema/🦀️.rs"]
mod artifact_link_schema;
pub use artifact_link_schema::{ArtifactLink, LinkPin};

/// @emoji 🌳️ Lets a snapshot type declare its own composed children / referenced links. Both
/// methods default to empty, so a leaf artifact (the overwhelming majority) needs zero
/// boilerplate — only a technology that actually embeds `ArtifactChild<S>`/`ArtifactLink` fields
/// overrides them (typically derive-generated in a later wave, per the design doc's
/// `ChildSlotSpec`/`LinkSlotSpec` schema facets).
pub trait ArtifactRefs {
    async fn child_refs(&self) -> Vec<ChildRef> {
        Vec::new()
    }
    async fn links(&self) -> Vec<ArtifactLink> {
        Vec::new()
    }
}

/// @emoji 🔎️ What resolving one `ArtifactLink` found: the target materialized as real bytes, that
/// it is simply absent, or (for a `LinkPin::Snapshot`) only the escrowed blob reference is known
/// without the resolver having fetched its bytes yet.
#[derive(Clone, Debug, PartialEq)]
pub enum LinkState {
    Resolved { pack_bytes: Vec<u8>, dialect: crate::os_io::ArtifactDialect },
    Missing,
    PinnedOnly { blob: BlobRef },
}

/// @emoji 🕵️ Host-side, LAZY link resolution — never called during `CompositionCoordinator`
/// dispatch (links have no bearing on group-atomicity: unlike a child, a link's target is not part
/// of this artifact's own document and dispatch never touches it). A UI/renderer calls this only
/// when it actually needs to show/open the linked content.
pub trait LinkResolver {
    async fn resolve(&self, link: &ArtifactLink) -> LinkState;
}

/// @emoji 🗂️ The read-only directory a `MemberLinkResolver` resolves against — whatever holds the
/// live members (a `SpaceHost`, or a test fixture). Returns owned PACK bytes rather than a
/// `&dyn SpaceMember` so the resolver can be OWNED and stored (a borrowed member reference could
/// never live in a long-lived host field), and `Option<Result<..>>` distinguishes "no such member"
/// (→ `LinkState::Missing`) from "member exists but reading it failed" (→ a real error, never
/// silently reported as absent).
pub trait MemberDirectory {
    async fn head_pack(&self, artifact_id: &str) -> Option<Result<Vec<u8>, VcsError>>;
    async fn checkpoint_pack(&self, artifact_id: &str, checkpoint_id: &str) -> Option<Result<Vec<u8>, VcsError>>;
}

impl MemberDirectory for SpaceHost {
    async fn head_pack(&self, artifact_id: &str) -> Option<Result<Vec<u8>, VcsError>> {
        match self.member(artifact_id).await {
            Some(member) => Some(member.document_pack_bytes().await),
            None => None,
        }
    }

    async fn checkpoint_pack(&self, artifact_id: &str, checkpoint_id: &str) -> Option<Result<Vec<u8>, VcsError>> {
        match self.member(artifact_id).await {
            Some(member) => Some(member.pack_at_checkpoint(checkpoint_id).await),
            None => None,
        }
    }
}

/// @emoji 🕵️ The one production `LinkResolver`: resolves each `LinkPin` against a `MemberDirectory`
/// (plus an optional `BlobStore` for escrowed snapshot pins). This is what makes "referenced
/// artifacts with their own version history" real — `Head` reads the target's live tip, while
/// `Checkpoint` reads the target's content AS OF that checkpoint, so a pinned reference keeps
/// showing what it was pinned to no matter how far the target has since moved.
///
/// A `Snapshot` pin with no blob store, or whose bytes are not in the store, degrades to
/// `PinnedOnly` — the blob reference is still known and displayable (a chip can render "pinned to
/// <hash>" without the content), which is precisely the state `LinkState::PinnedOnly` exists for.
/// A read error is never laundered into `Missing`: absence and failure are different answers, and
/// only absence is benign.
/// @emoji 🕳️ The default `B` for a `MemberLinkResolver` that carries no blob escrow — uninhabited,
/// same stand-in shape as `BackboneChannelPorts`/`NoMembers`, so `MemberLinkResolver::new` never
/// needs its caller to name a concrete `BlobStore` implementor it isn't using.
pub enum NoBlobStore {}

impl BlobStore for NoBlobStore {
    async fn put(&self, _bytes: &[u8], _media_type: &str) -> Result<BlobRef, VcsError> {
        match *self {}
    }

    async fn get(&self, _hash: &str) -> Result<Option<Vec<u8>>, VcsError> {
        match *self {}
    }

    async fn has(&self, _hash: &str) -> Result<bool, VcsError> {
        match *self {}
    }

    async fn delete(&self, _hash: &str) -> Result<(), VcsError> {
        match *self {}
    }
}

pub struct MemberLinkResolver<D, B = NoBlobStore> {
    directory: D,
    blobs: Option<Arc<B>>,
}

impl<D: MemberDirectory> MemberLinkResolver<D, NoBlobStore> {
    /// 🏗️ Resolver without blob escrow — `LinkPin::Snapshot` always degrades to `PinnedOnly`.
    pub async fn new(directory: D) -> Self {
        Self { directory, blobs: None }
    }
}

impl<D: MemberDirectory, B: BlobStore> MemberLinkResolver<D, B> {
    /// 🏗️ Resolver that can also materialize content-addressed `LinkPin::Snapshot` blobs.
    pub async fn with_blobs(directory: D, blobs: Arc<B>) -> Self {
        Self { directory, blobs: Some(blobs) }
    }
}

impl<D: MemberDirectory, B: BlobStore> LinkResolver for MemberLinkResolver<D, B> {
    async fn resolve(&self, link: &ArtifactLink) -> LinkState {
        let dialect = link.target.dialect.clone();
        match &link.pin {
            LinkPin::Head => match self.directory.head_pack(&link.target.artifact_id).await {
                Some(Ok(pack_bytes)) => LinkState::Resolved { pack_bytes, dialect },
                Some(Err(_)) | None => LinkState::Missing,
            },
            LinkPin::Checkpoint { id } => match self.directory.checkpoint_pack(&link.target.artifact_id, id).await {
                Some(Ok(pack_bytes)) => LinkState::Resolved { pack_bytes, dialect },
                Some(Err(_)) | None => LinkState::Missing,
            },
            LinkPin::Snapshot { blob } => {
                let resolved = match &self.blobs {
                    Some(blobs) => blobs.get(&blob.hash).await.ok().flatten(),
                    None => None,
                };
                match resolved {
                    Some(pack_bytes) => LinkState::Resolved { pack_bytes, dialect },
                    None => LinkState::PinnedOnly { blob: blob.clone() },
                }
            }
        }
    }
}

/// @emoji 🏭️ Generic genesis-construction helper every `space_members!`-generated `MemberFactory::
/// create` arm calls — the composition sibling of `ArtifactCodec`/`register_document_codec` above.
/// Bakes a brand-new child store from a freshly-baked initial pack (composition genesis, see
/// `CompositionCoordinator::dispatch_group`): `initial_pack` decoded as `P` (empty rejected — a
/// genesis caller always has an initial snapshot, and silently substituting `P::default()` would
/// mint a child whose content nobody chose), stamped with `dialect`. Replaces the old
/// `ChildStoreFactory`/`TypedChildStoreFactory` object-erased pair (O1 — a global `Arc<dyn
/// ChildStoreFactory>` registry keyed by runtime kind string is exactly the dyn-dispatched seam the
/// program drops): the registry's kind-keying now lives in the generated enum's own `match kind`.
pub async fn create_member_store<P, Mutation>(schema: &str, id: &str, dialect: &crate::os_io::ArtifactDialect, initial_pack: &[u8]) -> Result<ArtifactStore<P, Mutation>, VcsError>
where
    P: Clone + ToValue + FromValue + ArtifactPack + MemberStoreOwner<Mutation> + Send + 'static,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    if initial_pack.is_empty() {
        return Err(VcsError::Deserialize(format!("child genesis for {id} carries an empty initial pack")));
    }
    let initial = P::decode_pack(initial_pack).map_err(|error| VcsError::Deserialize(error.to_string()))?;
    let mut envelope = create_document_envelope::<P, Mutation>(schema, id, initial, None);
    envelope.dialect = Some(dialect.clone());
    let mut store = ArtifactStore::new(envelope).await?;
    store.install_document_store_owners_exact(P::member_store_owners());
    Ok(store)
}

/// @emoji 🏭️ Generic reload helper every `space_members!`-generated `MemberFactory::open` arm
/// calls — reconstructs a previously-persisted child from its full envelope pack via the same
/// `parse_document_pack` → `reset(envelope, applied, redo)` path `apply_ops_binary` uses, so a
/// reloaded child restores its exact undo/redo cursor position, not merely its content. The
/// invariant is `owner.is_some() ⇒ dialect.is_some()` — every envelope that is somebody's child
/// knows which dialect it materializes as, which is what lets `ArtifactView.children` type a child
/// without consulting the parent.
pub async fn open_member_store<P, Mutation>(schema: &str, expected: &crate::os_io::ArtifactRef, owner: Option<&OwnerRef>, envelope_pack: &[u8]) -> Result<ArtifactStore<P, Mutation>, VcsError>
where
    P: Clone + ToValue + FromValue + ArtifactPack + MemberStoreOwner<Mutation> + Send + 'static,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P> + OpBinary + OpText + Send + 'static,
{
    if owner.is_some_and(|owner| owner.child_id != expected.artifact_id) {
        return Err(VcsError::Deserialize("member owner child identity does not match requested artifact".into()));
    }
    let (pack, spr) = decode_document_pack_bytes(envelope_pack).await?;
    let history = crate::os_spr::decode_history(&spr, &crate::os_spr::DecodeOptions::default()).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
    validate_member_history_identity(&history, schema, expected, owner)?;
    let parsed = parse_decoded_document_spr::<P, Mutation>(&pack, history).await.map_err(|error| VcsError::Deserialize(error.to_string()))?;
    let mut store = ArtifactStore::new(parsed.envelope).await?;
    store.install_document_store_owners_exact(P::member_store_owners());
    Ok(store)
}

fn validate_member_history_identity(history: &crate::os_spr::HistoryLog, schema: &str, expected: &crate::os_io::ArtifactRef, owner: Option<&OwnerRef>) -> Result<(), VcsError> {
    let persisted_dialect = history.composition.as_ref().and_then(|composition| composition.dialect.as_ref());
    let dialect_matches = persisted_dialect.is_some_and(|(kind, standard, subset)| kind == &expected.dialect.artifact_kind && standard == &expected.dialect.standard && subset == &expected.dialect.subset);
    let persisted_owner = history.composition.as_ref().and_then(|composition| composition.owner.as_ref());
    let owner_matches = match (persisted_owner, owner) {
        (None, None) => true,
        (Some((parent, slot, child_id)), Some(owner)) => slot == &owner.slot && child_id == &owner.child_id && child_id == &expected.artifact_id && crate::os_io::ArtifactRef::parse_uri(parent).is_ok_and(|parent| parent == owner.parent),
        _ => false,
    };
    if history.doc_id != expected.artifact_id || history.schema != schema || !dialect_matches || !owner_matches {
        return Err(VcsError::Deserialize("member envelope does not match requested identity, schema, dialect and ownership".into()));
    }
    Ok(())
}

//#region 🔖️CompositionDsl
/// 🧬️ Hand-crafted `crate::os_dsl::DslField` records for `ArtifactChild`/`OwnerRef`/`ArtifactLink`/
/// `LinkPin` (P6 idiom, the same one `BackboneMessage`'s `OpText`/`OpBinary` impls near
/// `🔖️Backbone` below use) — NOT new `Shape` variants: the design doc's deviation D1 deliberately
/// keeps `Shape` closed (it is exhaustively matched in ~20 files) and represents every new value
/// type here as an ordinary `Shape::Record`. `crate::os_io::ArtifactRef` fields encode as their
/// `to_uri()` wire string (`Shape::Text`) rather than requiring `ArtifactRef: DslField` itself —
/// same "own the codec at this edge, don't couple types across crates" reasoning `CompositionPin`
/// (in `🌿️vcs`) already applies to the identical field shape.
// 🚫️async: E4 fn-pointer slot — value stored in `Shape::Record(fn() -> RecordSpec)`
fn artifact_child_spec() -> crate::os_dsl::RecordSpec {
    crate::os_dsl::RecordSpec::new(None, crate::os_dsl::RecordLayout::Inline, vec![crate::os_dsl::FieldSpec::new(0, "child_id", crate::os_dsl::Shape::Text), crate::os_dsl::FieldSpec::new(1, "target", crate::os_dsl::Shape::Text)])
}

// 🚫️async: E1 pure — record conversion with no suspension point, consumed by the sync
// `DslField::to_value` impl below. See R9.
fn artifact_child_to_record<S>(child: &ArtifactChild<S>) -> crate::os_dsl::RecordValue {
    let mut record = crate::os_dsl::RecordValue::default();
    record.fields.insert(0, crate::os_dsl::FieldValue::Text(child.child_id.clone()));
    record.fields.insert(1, crate::os_dsl::FieldValue::Text(child.target.to_uri()));
    record
}

// 🚫️async: E1 pure — same sync consumer as `artifact_child_to_record`. See R9.
fn artifact_child_from_record<S>(record: &crate::os_dsl::RecordValue) -> Result<ArtifactChild<S>, String> {
    let child_id = match record.get(0) {
        Some(crate::os_dsl::FieldValue::Text(s)) => s.clone(),
        other => return Err(format!("expected child_id, found {other:?}")),
    };
    let target = match record.get(1) {
        Some(crate::os_dsl::FieldValue::Text(s)) => crate::os_io::ArtifactRef::parse_uri(s)?,
        other => return Err(format!("expected target, found {other:?}")),
    };
    // 🧱️ Constructed directly rather than through the still-async `ArtifactChild::new`: this fn is
    // sync (E1, above) and `new` is a plain struct literal, so inlining it here avoids forcing an
    // async->sync flip across `new`'s 108 call sites in crates other packets own.
    Ok(ArtifactChild { child_id, target, local_owner: None, _snapshot: PhantomData })
}

impl<S> crate::os_dsl::DslField for ArtifactChild<S> {
    // 🚫️async: E4 — see `DslField::shape`'s tag on the trait.
    fn shape() -> crate::os_dsl::Shape {
        crate::os_dsl::Shape::Record(artifact_child_spec)
    }
    fn to_value(&self) -> crate::os_dsl::FieldValue {
        crate::os_dsl::FieldValue::Record(artifact_child_to_record(self))
    }
    fn from_value(value: &crate::os_dsl::FieldValue) -> Result<Self, String> {
        match value {
            crate::os_dsl::FieldValue::Record(record) => artifact_child_from_record(record),
            other => Err(format!("expected Record, found {other:?}")),
        }
    }
}

// 🚫️async: E4 fn-pointer slot — value stored in `Shape::Record(fn() -> RecordSpec)`
fn owner_ref_spec() -> crate::os_dsl::RecordSpec {
    crate::os_dsl::RecordSpec::new(
        None,
        crate::os_dsl::RecordLayout::Inline,
        vec![crate::os_dsl::FieldSpec::new(0, "parent", crate::os_dsl::Shape::Text), crate::os_dsl::FieldSpec::new(1, "slot", crate::os_dsl::Shape::Text), crate::os_dsl::FieldSpec::new(2, "child_id", crate::os_dsl::Shape::Text)],
    )
}

fn owner_ref_to_record(owner: &OwnerRef) -> crate::os_dsl::RecordValue {
    let mut record = crate::os_dsl::RecordValue::default();
    record.fields.insert(0, crate::os_dsl::FieldValue::Text(owner.parent.to_uri()));
    record.fields.insert(1, crate::os_dsl::FieldValue::Text(owner.slot.clone()));
    record.fields.insert(2, crate::os_dsl::FieldValue::Text(owner.child_id.clone()));
    record
}

fn owner_ref_from_record(record: &crate::os_dsl::RecordValue) -> Result<OwnerRef, String> {
    let parent = match record.get(0) {
        Some(crate::os_dsl::FieldValue::Text(s)) => crate::os_io::ArtifactRef::parse_uri(s)?,
        other => return Err(format!("expected parent, found {other:?}")),
    };
    let slot = match record.get(1) {
        Some(crate::os_dsl::FieldValue::Text(s)) => s.clone(),
        other => return Err(format!("expected slot, found {other:?}")),
    };
    let child_id = match record.get(2) {
        Some(crate::os_dsl::FieldValue::Text(s)) => s.clone(),
        other => return Err(format!("expected child_id, found {other:?}")),
    };
    Ok(OwnerRef { parent, slot, child_id })
}

impl crate::os_dsl::DslField for OwnerRef {
    // 🚫️async: E4 — see `DslField::shape`'s tag on the trait.
    fn shape() -> crate::os_dsl::Shape {
        crate::os_dsl::Shape::Record(owner_ref_spec)
    }
    fn to_value(&self) -> crate::os_dsl::FieldValue {
        crate::os_dsl::FieldValue::Record(owner_ref_to_record(self))
    }
    fn from_value(value: &crate::os_dsl::FieldValue) -> Result<Self, String> {
        match value {
            crate::os_dsl::FieldValue::Record(record) => owner_ref_from_record(record),
            other => Err(format!("expected Record, found {other:?}")),
        }
    }
}

// 🚫️async: E4 fn-pointer slot — value stored in `Shape::Record(fn() -> RecordSpec)`
fn link_pin_spec() -> crate::os_dsl::RecordSpec {
    crate::os_dsl::RecordSpec::new(
        None,
        crate::os_dsl::RecordLayout::Inline,
        vec![
            crate::os_dsl::FieldSpec::new(0, "kind", crate::os_dsl::Shape::Enum(vec![("head".to_string(), 0), ("checkpoint".to_string(), 1), ("snapshot".to_string(), 2)])),
            crate::os_dsl::FieldSpec::new(1, "checkpoint_id", crate::os_dsl::Shape::Text).optional(),
            crate::os_dsl::FieldSpec::new(2, "blob_hash", crate::os_dsl::Shape::Text).optional(),
            crate::os_dsl::FieldSpec::new(3, "blob_size", crate::os_dsl::Shape::UInt).optional(),
            crate::os_dsl::FieldSpec::new(4, "blob_media_type", crate::os_dsl::Shape::Text).optional(),
        ],
    )
}

fn link_pin_to_record(pin: &LinkPin) -> crate::os_dsl::RecordValue {
    let mut record = crate::os_dsl::RecordValue::default();
    match pin {
        LinkPin::Head => {
            record.fields.insert(0, crate::os_dsl::FieldValue::Enum(0));
        }
        LinkPin::Checkpoint { id } => {
            record.fields.insert(0, crate::os_dsl::FieldValue::Enum(1));
            record.fields.insert(1, crate::os_dsl::FieldValue::Text(id.clone()));
        }
        LinkPin::Snapshot { blob } => {
            record.fields.insert(0, crate::os_dsl::FieldValue::Enum(2));
            record.fields.insert(2, crate::os_dsl::FieldValue::Text(blob.hash.clone()));
            record.fields.insert(3, crate::os_dsl::FieldValue::UInt(blob.size));
            record.fields.insert(4, crate::os_dsl::FieldValue::Text(blob.media_type.clone()));
        }
    }
    record
}

fn link_pin_from_record(record: &crate::os_dsl::RecordValue) -> Result<LinkPin, String> {
    let ordinal = match record.get(0) {
        Some(crate::os_dsl::FieldValue::Enum(n)) => *n,
        other => return Err(format!("expected kind, found {other:?}")),
    };
    match ordinal {
        0 => Ok(LinkPin::Head),
        1 => {
            let id = match record.get(1) {
                Some(crate::os_dsl::FieldValue::Text(s)) => s.clone(),
                other => return Err(format!("expected checkpoint_id, found {other:?}")),
            };
            Ok(LinkPin::Checkpoint { id })
        }
        2 => {
            let hash = match record.get(2) {
                Some(crate::os_dsl::FieldValue::Text(s)) => s.clone(),
                other => return Err(format!("expected blob_hash, found {other:?}")),
            };
            let size = match record.get(3) {
                Some(crate::os_dsl::FieldValue::UInt(n)) => *n,
                other => return Err(format!("expected blob_size, found {other:?}")),
            };
            let media_type = match record.get(4) {
                Some(crate::os_dsl::FieldValue::Text(s)) => s.clone(),
                other => return Err(format!("expected blob_media_type, found {other:?}")),
            };
            Ok(LinkPin::Snapshot { blob: BlobRef { hash, size, media_type } })
        }
        other => Err(format!("unknown link pin kind ordinal {other}")),
    }
}

impl crate::os_dsl::DslField for LinkPin {
    // 🚫️async: E4 — see `DslField::shape`'s tag on the trait.
    fn shape() -> crate::os_dsl::Shape {
        crate::os_dsl::Shape::Record(link_pin_spec)
    }
    fn to_value(&self) -> crate::os_dsl::FieldValue {
        crate::os_dsl::FieldValue::Record(link_pin_to_record(self))
    }
    fn from_value(value: &crate::os_dsl::FieldValue) -> Result<Self, String> {
        match value {
            crate::os_dsl::FieldValue::Record(record) => link_pin_from_record(record),
            other => Err(format!("expected Record, found {other:?}")),
        }
    }
}

// 🚫️async: E4 fn-pointer slot — value stored in `Shape::Record(fn() -> RecordSpec)`
fn artifact_link_spec() -> crate::os_dsl::RecordSpec {
    crate::os_dsl::RecordSpec::new(
        None,
        crate::os_dsl::RecordLayout::Inline,
        vec![crate::os_dsl::FieldSpec::new(0, "target", crate::os_dsl::Shape::Text), crate::os_dsl::FieldSpec::new(1, "pin", crate::os_dsl::Shape::Record(link_pin_spec)), crate::os_dsl::FieldSpec::new(2, "role", crate::os_dsl::Shape::Text)],
    )
}

fn artifact_link_to_record(link: &ArtifactLink) -> crate::os_dsl::RecordValue {
    let mut record = crate::os_dsl::RecordValue::default();
    record.fields.insert(0, crate::os_dsl::FieldValue::Text(link.target.to_uri()));
    record.fields.insert(1, crate::os_dsl::FieldValue::Record(link_pin_to_record(&link.pin)));
    record.fields.insert(2, crate::os_dsl::FieldValue::Text(link.role.clone()));
    record
}

fn artifact_link_from_record(record: &crate::os_dsl::RecordValue) -> Result<ArtifactLink, String> {
    let target = match record.get(0) {
        Some(crate::os_dsl::FieldValue::Text(s)) => crate::os_io::ArtifactRef::parse_uri(s)?,
        other => return Err(format!("expected target, found {other:?}")),
    };
    let pin = match record.get(1) {
        Some(crate::os_dsl::FieldValue::Record(record)) => link_pin_from_record(record)?,
        other => return Err(format!("expected pin, found {other:?}")),
    };
    let role = match record.get(2) {
        Some(crate::os_dsl::FieldValue::Text(s)) => s.clone(),
        other => return Err(format!("expected role, found {other:?}")),
    };
    Ok(ArtifactLink { target, pin, role })
}

impl crate::os_dsl::DslField for ArtifactLink {
    // 🚫️async: E4 — see `DslField::shape`'s tag on the trait.
    fn shape() -> crate::os_dsl::Shape {
        crate::os_dsl::Shape::Record(artifact_link_spec)
    }
    fn to_value(&self) -> crate::os_dsl::FieldValue {
        crate::os_dsl::FieldValue::Record(artifact_link_to_record(self))
    }
    fn from_value(value: &crate::os_dsl::FieldValue) -> Result<Self, String> {
        match value {
            crate::os_dsl::FieldValue::Record(record) => artifact_link_from_record(record),
            other => Err(format!("expected Record, found {other:?}")),
        }
    }
}
//#endregion 🔖️CompositionDsl
//#endregion 🔖️Composition

//#region 🔖️Authority
/// @emoji 🧾 Receipt from the sole store write gate (`dispatch` / `reset`). `messages`/`worst` carry
/// whatever `crate::os_spr::MutationMessage`s the command's own replay produced (empty/`None` for a
/// structural command with nothing to report) — `26/08/16/MUTATION-OUTCOMES-MERGE-POLICIES-AND-
/// FIRST-CLASS-CONFLICTS` §C6. `Eq` dropped (was `#[derive(.., PartialEq, Eq)]`): `EditMessages`
/// only derives `PartialEq`.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CommandReceipt {
    pub edit_ids: Vec<String>,
    pub generation: u64,
    pub messages: Vec<crate::os_spr::EditMessages>,
    pub worst: Option<crate::os_dsl::Severity>,
}

//#region 🔮️Projection
//#region 🧭️Stamps
/// 🧬️ History identity for a projection input, independent of the process-local generation.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ArtifactRevision {
    pub artifact_id: String,
    pub schema: String,
    pub applied_edit_ids: Vec<String>,
    pub redo_edit_ids: Vec<String>,
    pub checkpoint_id: Option<String>,
}

/// 🎯️ Exact state identity a projection or inference result must match before it is accepted.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct ArtifactProjectionStamp {
    pub revision: ArtifactRevision,
    pub generation: u64,
}

/// 🔄️ Store transition that produced a projection input.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ArtifactProjectionCause {
    Apply,
    RemoteIngest,
    Replay,
    Undo,
    Redo,
    Reset,
    Checkout,
    PolicyChange,
    ExternalResourceChange,
    Checkpoint,
    PruneDrafts,
}

/// 🗄️ Explicit prior-result handling; projections never infer cache authority from state alone.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum ArtifactProjectionCacheMode {
    Rebuild,
    ReusePrevious,
    ValidatePrevious,
}
//#endregion 🧭️Stamps

//#region 📡️Events
/// 📬️ Typed projection/inference input carrying the exact artifact version it observed.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ArtifactProjectionEvent<State, Previous, Policy> {
    pub stamp: ArtifactProjectionStamp,
    pub cause: ArtifactProjectionCause,
    pub state: State,
    pub previous: Option<Previous>,
    pub cache_mode: ArtifactProjectionCacheMode,
    pub policy: Policy,
}

/// 🧩️ Projection output plus an optional semantic-diff candidate. This layer validates freshness;
/// strict `ArtifactDiff` application stays owned by the semantic-mutation boundary.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ArtifactProjectionResult<Output, Diff = ()> {
    pub stamp: ArtifactProjectionStamp,
    pub output: Output,
    pub proposed_diff: Option<Diff>,
}

impl<State, Previous, Policy> ArtifactProjectionEvent<State, Previous, Policy> {
    /// 🧪️ Couples an asynchronously computed result to this event's immutable stamp.
    pub async fn result<Output, Diff>(&self, output: Output, proposed_diff: Option<Diff>) -> ArtifactProjectionResult<Output, Diff> {
        ArtifactProjectionResult { stamp: self.stamp.clone(), output, proposed_diff }
    }
}

/// ✅️ A current projection result, intentionally separated from semantic-diff application.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct AcceptedArtifactProjection<Output, Diff = ()> {
    pub output: Output,
    pub proposed_diff: Option<Diff>,
}

/// 🚫️ A result computed against an older state and therefore forbidden from changing current state.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct StaleArtifactProjection {
    pub computed_for: ArtifactProjectionStamp,
    pub current: ArtifactProjectionStamp,
}

/// 📣️ One state or dependency transition that invalidates derived artifact work.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ArtifactProjectionInvalidation {
    pub cause: ArtifactProjectionCause,
    pub stamp: ArtifactProjectionStamp,
}
//#endregion 📡️Events
//#endregion 🔮️Projection

/// @emoji 👁️ Read-only view over a document envelope — mutation is sealed through `dispatch`/`reset`.
#[derive(Clone, Copy, Debug)]
pub struct ArtifactEnvelopeView<'a, P, Mutation> {
    envelope: &'a ArtifactEnvelope<P, Mutation>,
}

impl<'a, P, Mutation> ArtifactEnvelopeView<'a, P, Mutation> {
    pub async fn schema(&self) -> &str {
        &self.envelope.schema
    }
    pub async fn id(&self) -> &str {
        &self.envelope.id
    }
    pub async fn vcs(&self) -> &ArtifactVcs<P, Mutation> {
        &self.envelope.vcs
    }
    pub async fn backbone(&self) -> Option<&ArtifactBackboneRef> {
        self.envelope.backbone.as_ref()
    }
    pub async fn active_alternative_id(&self) -> Option<&str> {
        self.envelope.active_alternative_id.as_deref()
    }
    pub async fn cursor(&self) -> Option<&ArtifactCursor> {
        self.envelope.cursor.as_ref()
    }
    pub async fn edit_messages(&self) -> &ArtifactEditMessageLedger {
        &self.envelope.edit_messages
    }
    pub async fn conflicts(&self) -> &[crate::os_spr::Conflict] {
        &self.envelope.conflicts
    }
    pub async fn inner(&self) -> &'a ArtifactEnvelope<P, Mutation> {
        self.envelope
    }
}

/// @emoji 📝 Draft-lane store alias — same algebra as ArtifactStore; PruneDrafts never enters a Change.
pub type DraftStore<P, Mutation> = ArtifactStore<P, Mutation>;

//#region 🔖️EphemeralLanes
/// 🧬️ Exact witness returned after one, and only one, lane item changes a live root.
/// 🌉️ Carries serde alongside `ToValue`/`FromValue`: `TypedOperationResultPage::try_serialize`
/// (`🔌️plugin/🦀️.rs`) is bound on `serde::Serialize`, and both fields are `u64`, so the derives add
/// no bound fan-out. `rename_all` is mirrored so the two encodings emit the same keys.
#[derive(Clone, Copy, Debug, PartialEq, Eq, ToValue, FromValue, serde::Serialize, serde::Deserialize)]
#[value(rename_all = "camelCase")]
#[serde(rename_all = "camelCase")]
pub struct LaneItemReceipt {
    pub generation_before: u64,
    pub generation_after: u64,
}

//#region 📬️EphemeralOneItemPublication
pub struct ArtifactEphemeralOneItemPrepared<P> {
    pub next_root: Arc<P>,
}

pub struct ArtifactEphemeralBaseRead<P>(pub ArtifactEphemeralBaseOwner<P>);

/// 🫧️ Which owner a preparation's base came from. Public so an app can build the exact request its
/// own registered ephemeral preparation factory receives, and drive it directly in a conformance
/// test, without standing up the whole presence/transient store around it.
pub enum ArtifactEphemeralBaseOwner<P> {
    Presence(SnapshotRead<P>),
    Transient(Arc<P>),
    TransientRead(SnapshotRead<P>),
}

impl<P> AsRef<P> for ArtifactEphemeralBaseRead<P> {
    fn as_ref(&self) -> &P {
        match &self.0 {
            ArtifactEphemeralBaseOwner::Presence(read) => read.get(),
            ArtifactEphemeralBaseOwner::Transient(root) => root.as_ref(),
            ArtifactEphemeralBaseOwner::TransientRead(read) => read.get(),
        }
    }
}

impl<P> std::ops::Deref for ArtifactEphemeralBaseRead<P> {
    type Target = P;
    fn deref(&self) -> &P {
        self.as_ref()
    }
}

pub struct ArtifactEphemeralOneItemPreparationRequest<P, Mutation> {
    pub operation: semio_framework_job::OperationId,
    pub generation: semio_framework_job::Generation,
    pub base: ArtifactEphemeralBaseRead<P>,
    pub mutation: Mutation,
}

pub trait ArtifactEphemeralOneItemPreparation<P, Mutation>: Send {
    fn advance(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<ArtifactStoreOneItemPreparationStep, String>;
    fn checkpoint(&self) -> ArtifactStoreOneItemCheckpoint;
    fn prepared(&self) -> Option<&ArtifactEphemeralOneItemPrepared<P>>;
    fn take_prepared(&mut self) -> Option<ArtifactEphemeralOneItemPrepared<P>>;
    fn cancel(&mut self);
    fn begin_close(&mut self);
    fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, String>;
    fn terminal_is_empty(&self) -> bool;
}

pub trait ArtifactEphemeralOneItemPreparationFactory<P, Mutation>: Send + Sync {
    fn preflight(&self, mutation: &Mutation) -> Result<ArtifactStoreOneItemFootprint, String>;
    fn begin(&self, request: ArtifactEphemeralOneItemPreparationRequest<P, Mutation>) -> Result<Box<dyn ArtifactEphemeralOneItemPreparation<P, Mutation>>, ArtifactEphemeralOneItemPreparationRequest<P, Mutation>>;
}

#[derive(Debug)]
pub struct ArtifactEphemeralOneItemAdmissionRejected<Mutation> {
    pub reason: String,
    pub mutation: Mutation,
}

impl<Mutation> ArtifactEphemeralOneItemAdmissionRejected<Mutation> {
    pub fn into_owners(self) -> (String, Mutation) {
        (self.reason, self.mutation)
    }
}

pub struct ArtifactEphemeralOneItemPublication<P, Mutation> {
    operation: semio_framework_job::OperationId,
    expected_generation: u64,
    footprint: ArtifactStoreOneItemFootprint,
    preparation: Option<Box<dyn ArtifactEphemeralOneItemPreparation<P, Mutation>>>,
    displaced_root_retirement: Option<Box<dyn ErasedSnapshotRetirement>>,
    root_retirement_factory: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    returned_read_registry: Option<Arc<SnapshotReadLeaseRegistry>>,
    returned_read_retirement: Option<Box<dyn ErasedSnapshotRetirement>>,
    owned_retirement_factory: Option<Arc<dyn ArtifactOwnedValueRetirementFactory<P>>>,
    receipt: Option<LaneItemReceipt>,
    attempts: u8,
    published: bool,
    cancel_requested: bool,
    close_started: bool,
    fault: Option<String>,
    phase: ArtifactStoreOneItemPublicationPhase,
}

impl<P, Mutation> ArtifactEphemeralOneItemPublication<P, Mutation> {
    pub fn operation(&self) -> semio_framework_job::OperationId {
        self.operation
    }

    pub fn phase(&self) -> ArtifactStoreOneItemPublicationPhase {
        self.phase
    }

    pub fn progress(&self) -> ArtifactStoreOneItemCheckpoint {
        self.preparation.as_ref().map_or_else(ArtifactStoreOneItemCheckpoint::default, |owner| owner.checkpoint())
    }

    pub fn fault(&self) -> Option<&str> {
        self.fault.as_deref()
    }

    fn advance_preparation(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<ArtifactStoreOneItemPreparationStep, String> {
        let result = self.preparation.as_mut().ok_or_else(|| "ephemeral publication lost its preparation owner".to_string()).and_then(|owner| {
            let step = owner.advance(ArtifactStoreOneItemGrant { maximum_items: grant.maximum_items.min(1), maximum_bytes: grant.maximum_bytes })?;
            if matches!(step, ArtifactStoreOneItemPreparationStep::Prepared(_)) && owner.prepared().is_none() {
                return Err("ephemeral preparation reported Prepared without its root".into());
            }
            Ok(step)
        });
        if let Err(reason) = &result {
            self.fault = Some(reason.clone());
            self.begin_close();
        }
        result
    }

    pub fn retry(&mut self) -> bool {
        if self.phase != ArtifactStoreOneItemPublicationPhase::AwaitingAck || self.attempts >= ARTIFACT_STORE_ONE_ITEM_MAXIMUM_RETRIES {
            return false;
        }
        self.attempts += 1;
        true
    }

    pub fn acknowledge(&mut self) -> bool {
        if self.phase != ArtifactStoreOneItemPublicationPhase::AwaitingAck {
            return false;
        }
        self.phase = ArtifactStoreOneItemPublicationPhase::Closing;
        self.begin_close();
        true
    }

    pub fn begin_close(&mut self) {
        if self.close_started {
            return;
        }
        self.close_started = true;
        self.phase = if self.phase == ArtifactStoreOneItemPublicationPhase::Complete { ArtifactStoreOneItemPublicationPhase::Complete } else { ArtifactStoreOneItemPublicationPhase::Closing };
        if let Some(owner) = self.preparation.as_mut() {
            if !self.published {
                self.cancel_requested = true;
                owner.cancel();
            }
            owner.begin_close();
        }
    }

    pub fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, String>
    where
        P: Send + Sync + 'static,
    {
        self.begin_close();
        if let Some(owner) = self.preparation.as_mut() {
            let step = owner.close_step(ArtifactStoreOneItemGrant { maximum_items: grant.maximum_items.min(1), maximum_bytes: grant.maximum_bytes })?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !owner.terminal_is_empty() {
                return Err("ephemeral one-item preparation reported complete without terminal emptiness".into());
            }
            self.preparation = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let (Some(registry), Some(factory)) = (self.returned_read_registry.as_ref(), self.owned_retirement_factory.as_ref()) {
            let step = advance_returned_snapshot_read(registry, &mut self.returned_read_retirement, factory, grant.maximum_items.min(1), grant.maximum_bytes)?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
        }
        if let Some(owner) = self.displaced_root_retirement.as_mut() {
            let step = owner.close_step(grant.maximum_items.min(1), grant.maximum_bytes)?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !owner.terminal_is_empty() {
                return Err("ephemeral displaced-root retirement reported complete without terminal emptiness".into());
            }
            self.displaced_root_retirement = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        self.root_retirement_factory = None;
        self.returned_read_registry = None;
        self.owned_retirement_factory = None;
        if grant.maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if self.receipt.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(fault) = self.fault.as_mut().filter(|fault| !fault.is_empty()) {
            let scalar = fault.chars().next_back().expect("nonempty ephemeral publication fault");
            if scalar.len_utf8() > grant.maximum_bytes {
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
            }
            fault.pop();
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: scalar.len_utf8() });
        }
        self.fault = None;
        self.phase = ArtifactStoreOneItemPublicationPhase::Complete;
        Ok(SnapshotRetirementStep::Complete)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.phase == ArtifactStoreOneItemPublicationPhase::Complete
            && self.preparation.is_none()
            && self.displaced_root_retirement.is_none()
            && self.root_retirement_factory.is_none()
            && self.returned_read_registry.is_none()
            && self.returned_read_retirement.is_none()
            && self.owned_retirement_factory.is_none()
            && self.receipt.is_none()
            && self.fault.is_none()
    }
}

impl<P, Mutation> Drop for ArtifactEphemeralOneItemPublication<P, Mutation> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "ephemeral one-item publication reached Drop without its terminal-empty witness");
    }
}
//#endregion 📬️EphemeralOneItemPublication

/// @emoji 👥️ The PRESENCE lane's store: ephemeral SHARED state — a last-writer-wins roster, NOT an
/// event log.
///
/// 🎯️ Why not `ArtifactStore` (which `ConfigStore`/`DraftStore` both alias): presence has no
/// history, no undo, no checkpoints and no merge. Each peer is the sole author of its own presence
/// value, and the wire already carries whole encoded snapshots per peer
/// (`ClientFrame::Presence { peer }` / `ServerFrame::Presence { peers }`), so a later frame from a
/// peer simply SUPERSEDES its earlier one. Modelling that as an op log would mint an unbounded
/// history of cursor positions nobody can ever undo.
///
/// `generation` bumps on every local change so the host can tell "something to broadcast" from
/// "nothing changed" without diffing snapshots — the signal a heartbeat coalescer throttles on.
pub struct PresenceStore<P, Mutation> {
    local: std::mem::ManuallyDrop<Arc<P>>,
    peers: std::mem::ManuallyDrop<Arc<PresencePeersRoot<P>>>,
    peer_retirement_factory: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    local_retirement_factory: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    local_reads: std::mem::ManuallyDrop<Arc<SnapshotReadLeaseRegistry>>,
    active_returned_local: std::mem::ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,
    generation: u64,
    close_started: bool,
    _mutation: PhantomData<fn() -> Mutation>,
}

pub const PRESENCE_PEER_SLOTS: usize = 64;
pub const PRESENCE_PEER_ID_BYTES: usize = 256;

#[derive(Debug)]
struct PresencePeerEntry<P> {
    actor: std::mem::ManuallyDrop<String>,
    presence: std::mem::ManuallyDrop<Option<Arc<P>>>,
    received_at_ms: i64,
}

impl<P> PresencePeerEntry<P> {
    fn new(actor: String, presence: Arc<P>, received_at_ms: i64) -> Self {
        Self { actor: std::mem::ManuallyDrop::new(actor), presence: std::mem::ManuallyDrop::new(Some(presence)), received_at_ms }
    }
}

impl<P> Drop for PresencePeerEntry<P> {
    fn drop(&mut self) {
        let terminal = self.actor.is_empty() && self.presence.is_none();
        if !std::thread::panicking() {
            assert!(std::thread::panicking() || (terminal), "presence peer entry requires exact final-owner retirement");
        }
        if terminal {
            unsafe {
                drop(std::mem::ManuallyDrop::take(&mut self.actor));
                drop(std::mem::ManuallyDrop::take(&mut self.presence));
            }
        }
    }
}

#[derive(Debug)]
pub struct PresencePeersRoot<P> {
    entries: [Option<Arc<PresencePeerEntry<P>>>; PRESENCE_PEER_SLOTS],
    len: usize,
}

impl<P> PresencePeersRoot<P> {
    fn clone_aliases(&self) -> Self {
        Self { entries: self.entries.clone(), len: self.len }
    }
}

impl<P> PresencePeersRoot<P> {
    pub fn empty() -> Self {
        Self { entries: std::array::from_fn(|_| None), len: 0 }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn peers(&self) -> impl Iterator<Item = (&str, &P)> {
        self.entries[..self.len].iter().filter_map(|entry| entry.as_deref().and_then(|entry| entry.presence.as_deref().map(|presence| (entry.actor.as_str(), presence))))
    }

    fn upsert(&self, actor: String, presence: P, received_at_ms: i64) -> Result<(Self, Option<Arc<PresencePeerEntry<P>>>), String> {
        if actor.is_empty() || actor.len() > PRESENCE_PEER_ID_BYTES {
            return Err("presence peer actor is empty or exceeds its fixed byte authority".into());
        }
        let mut next = self.clone_aliases();
        let mut index = 0usize;
        while index < next.len && next.entries[index].as_ref().is_some_and(|entry| entry.actor.as_str() < actor.as_str()) {
            index += 1;
        }
        if next.entries.get(index).and_then(Option::as_ref).is_some_and(|entry| entry.actor.as_str() == actor.as_str()) {
            let retired = next.entries[index].replace(Arc::new(PresencePeerEntry::new(actor, Arc::new(presence), received_at_ms)));
            return Ok((next, retired));
        }
        if next.len == PRESENCE_PEER_SLOTS {
            return Err("presence peer root exceeds its fixed item authority".into());
        }
        for cursor in (index..next.len).rev() {
            next.entries[cursor + 1] = next.entries[cursor].take();
        }
        next.entries[index] = Some(Arc::new(PresencePeerEntry::new(actor, Arc::new(presence), received_at_ms)));
        next.len += 1;
        Ok((next, None))
    }

    fn remove(&self, actor: &str) -> (Self, Option<Arc<PresencePeerEntry<P>>>) {
        let mut next = self.clone_aliases();
        let Some(index) = next.entries[..next.len].iter().position(|entry| entry.as_ref().is_some_and(|entry| entry.actor.as_str() == actor)) else {
            return (next, None);
        };
        let retired = next.entries[index].take();
        for cursor in index..next.len.saturating_sub(1) {
            next.entries[cursor] = next.entries[cursor + 1].take();
        }
        next.len = next.len.saturating_sub(1);
        next.entries[next.len] = None;
        (next, retired)
    }

    fn remove_at(&self, index: usize) -> (Self, Option<Arc<PresencePeerEntry<P>>>) {
        if index >= self.len {
            return (self.clone_aliases(), None);
        }
        let mut next = self.clone_aliases();
        let retired = next.entries[index].take();
        for cursor in index..next.len.saturating_sub(1) {
            next.entries[cursor] = next.entries[cursor + 1].take();
        }
        next.len = next.len.saturating_sub(1);
        next.entries[next.len] = None;
        (next, retired)
    }

    fn retain_received(&self, oldest_allowed_ms: i64) -> (Self, PresencePeersRetiredEntries<P>) {
        let mut next = Self::empty();
        let mut retired = PresencePeersRetiredEntries::empty();
        for entry in self.entries[..self.len].iter().filter_map(Option::as_ref) {
            if entry.received_at_ms >= oldest_allowed_ms {
                next.entries[next.len] = Some(entry.clone());
                next.len += 1;
            } else {
                retired.entries[retired.len] = Some(entry.clone());
                retired.len += 1;
            }
        }
        (next, retired)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PresencePeersCapacityError;

pub struct PresencePeersRetiredEntries<P> {
    entries: std::mem::ManuallyDrop<[Option<Arc<PresencePeerEntry<P>>>; PRESENCE_PEER_SLOTS]>,
    len: usize,
}

impl<P> PresencePeersRetiredEntries<P> {
    pub fn empty() -> Self {
        Self { entries: std::mem::ManuallyDrop::new(std::array::from_fn(|_| None)), len: 0 }
    }

    fn one(entry: Option<Arc<PresencePeerEntry<P>>>) -> Self {
        let mut retired = Self::empty();
        if let Some(entry) = entry {
            retired.entries[0] = Some(entry);
            retired.len = 1;
        }
        retired
    }

    pub fn append(&mut self, other: &mut Self) -> Result<(), PresencePeersCapacityError> {
        if self.len.saturating_add(other.len) > PRESENCE_PEER_SLOTS {
            return Err(PresencePeersCapacityError);
        }
        for index in 0..other.len {
            if let Some(entry) = other.entries[index].take() {
                self.entries[self.len] = Some(entry);
                self.len += 1;
            }
        }
        other.len = 0;
        Ok(())
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
}

impl<P> Drop for PresencePeersRetiredEntries<P> {
    fn drop(&mut self) {
        debug_assert!(self.is_empty(), "nonterminal app-typed presence retirement entries reached Drop");
    }
}

pub struct PresencePeersRetirement<P> {
    root: std::mem::ManuallyDrop<Option<Arc<PresencePeersRoot<P>>>>,
    owned_root: std::mem::ManuallyDrop<Option<PresencePeersRoot<P>>>,
    retired: std::mem::ManuallyDrop<PresencePeersRetiredEntries<P>>,
    waiting: std::mem::ManuallyDrop<Option<Arc<PresencePeerEntry<P>>>>,
    entry: std::mem::ManuallyDrop<Option<PresencePeerEntry<P>>>,
    active: std::mem::ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,
    factory: Arc<dyn SnapshotRetirementFactory<P>>,
    cursor: usize,
}

pub struct PresencePeersPublication<P> {
    base_root: std::mem::ManuallyDrop<Option<Arc<PresencePeersRoot<P>>>>,
    candidate: std::mem::ManuallyDrop<Option<PresencePeersRoot<P>>>,
    created: std::mem::ManuallyDrop<PresencePeersRetiredEntries<P>>,
    retired: std::mem::ManuallyDrop<PresencePeersRetiredEntries<P>>,
    active: std::mem::ManuallyDrop<Option<PresencePeersRetirement<P>>>,
    factory: Arc<dyn SnapshotRetirementFactory<P>>,
    prune_cursor: usize,
    pruning_complete: bool,
}

pub struct PresencePeersCommit<P> {
    base_root: Arc<PresencePeersRoot<P>>,
    root: Arc<PresencePeersRoot<P>>,
    retirement: Option<PresencePeersRetirement<P>>,
    factory: Arc<dyn SnapshotRetirementFactory<P>>,
}

#[path = "👥️presence/🚫️rejection/🦀️.rs"]
mod presence_peer_rejection;
pub use presence_peer_rejection::PresencePeerAdmissionRejected;

impl<P: Send + Sync + 'static> PresencePeersPublication<P> {
    fn new(current: &Arc<PresencePeersRoot<P>>, factory: Arc<dyn SnapshotRetirementFactory<P>>) -> Self {
        Self {
            base_root: std::mem::ManuallyDrop::new(Some(current.clone())),
            candidate: std::mem::ManuallyDrop::new(Some(current.clone_aliases())),
            created: std::mem::ManuallyDrop::new(PresencePeersRetiredEntries::empty()),
            retired: std::mem::ManuallyDrop::new(PresencePeersRetiredEntries::empty()),
            active: std::mem::ManuallyDrop::new(None),
            factory,
            prune_cursor: 0,
            pruning_complete: false,
        }
    }

    pub fn prune_one(&mut self, mut keep: impl FnMut(&str) -> bool) -> Result<bool, String> {
        if self.pruning_complete {
            return Ok(false);
        }
        let candidate = self.candidate.as_ref().ok_or_else(|| "presence peer publication candidate is not owned".to_string())?;
        if self.prune_cursor >= candidate.len {
            self.pruning_complete = true;
            return Ok(false);
        }
        let keep_entry = candidate.entries[self.prune_cursor].as_ref().is_some_and(|entry| keep(&entry.actor));
        if keep_entry {
            self.prune_cursor += 1;
            return Ok(true);
        }
        let (next, retired) = candidate.remove_at(self.prune_cursor);
        let previous = self.candidate.replace(next).expect("presence peer publication candidate");
        drop(previous);
        let mut retired = PresencePeersRetiredEntries::one(retired);
        self.retired.append(&mut retired).map_err(|_| "presence peer publication displaced-entry authority is saturated".to_string())?;
        Ok(true)
    }

    pub fn adopt(&mut self, actor: String, presence: P, received_at_ms: i64) -> Result<(), PresencePeerAdmissionRejected<P>> {
        if !self.pruning_complete {
            return Err(PresencePeerAdmissionRejected::new("presence peer publication must finish stale-entry pruning before decode adoption", actor, presence, self.factory.clone()));
        }
        let Some(candidate) = self.candidate.as_ref() else {
            return Err(PresencePeerAdmissionRejected::new("presence peer publication candidate is not owned", actor, presence, self.factory.clone()));
        };
        if actor.is_empty() || actor.len() > PRESENCE_PEER_ID_BYTES {
            return Err(PresencePeerAdmissionRejected::new("presence peer actor is empty or exceeds its fixed byte authority", actor, presence, self.factory.clone()));
        }
        if candidate.len == PRESENCE_PEER_SLOTS && !candidate.entries[..candidate.len].iter().any(|entry| entry.as_ref().is_some_and(|entry| entry.actor.as_str() == actor.as_str())) {
            return Err(PresencePeerAdmissionRejected::new("presence peer root exceeds its fixed item authority", actor, presence, self.factory.clone()));
        }
        let mut next = candidate.clone_aliases();
        let mut index = 0usize;
        while index < next.len && next.entries[index].as_ref().is_some_and(|entry| entry.actor.as_str() < actor.as_str()) {
            index += 1;
        }
        let replaces = next.entries.get(index).and_then(Option::as_ref).is_some_and(|entry| entry.actor.as_str() == actor.as_str());
        if self.created.len == PRESENCE_PEER_SLOTS || (replaces && self.retired.len == PRESENCE_PEER_SLOTS) {
            return Err(PresencePeerAdmissionRejected::new("presence peer publication ownership authority is saturated", actor, presence, self.factory.clone()));
        }
        let presence = Arc::new(presence);
        let inserted = Arc::new(PresencePeerEntry::new(actor, presence, received_at_ms));
        let retired = if replaces {
            next.entries[index].replace(inserted.clone())
        } else {
            for cursor in (index..next.len).rev() {
                next.entries[cursor + 1] = next.entries[cursor].take();
            }
            next.entries[index] = Some(inserted.clone());
            next.len += 1;
            None
        };
        let previous = self.candidate.replace(next).expect("presence peer publication candidate");
        drop(previous);
        let created_index = self.created.len;
        self.created.entries[created_index] = Some(inserted);
        self.created.len += 1;
        if let Some(retired) = retired {
            let retired_index = self.retired.len;
            self.retired.entries[retired_index] = Some(retired);
            self.retired.len += 1;
        }
        Ok(())
    }

    pub fn release_created_one(&mut self) -> bool {
        if self.created.len == 0 {
            return false;
        }
        self.created.len -= 1;
        let index = self.created.len;
        drop(self.created.entries[index].take());
        true
    }

    pub fn take_commit(&mut self) -> Result<PresencePeersCommit<P>, String> {
        if !self.pruning_complete || self.created.len != 0 || self.active.is_some() {
            return Err("presence peer publication is not terminal-ready for commit".into());
        }
        let candidate = Arc::new(self.candidate.take().ok_or_else(|| "presence peer publication candidate was already transferred".to_string())?);
        let retired = std::mem::replace(&mut *self.retired, PresencePeersRetiredEntries::empty());
        let retirement = (!retired.is_empty()).then(|| PresencePeersRetirement::new(retired, self.factory.clone()));
        Ok(PresencePeersCommit { base_root: self.base_root.take().expect("peer candidate retains its exact immutable base"), root: candidate, retirement, factory: self.factory.clone() })
    }

    pub fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, String> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(active) = self.active.as_mut() {
            let step = active.close_step(maximum_items, maximum_bytes)?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !active.terminal_is_empty() {
                return Err("presence peer publication cleanup reported Complete without its terminal-empty witness".into());
            }
            drop(self.active.take());
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(candidate) = self.candidate.as_mut() {
            if candidate.len != 0 {
                candidate.len -= 1;
                *self.active = Some(PresencePeersRetirement::new(PresencePeersRetiredEntries::one(candidate.entries[candidate.len].take()), self.factory.clone()));
                return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
            }
            drop(self.candidate.take());
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.retired.len != 0 {
            self.retired.len -= 1;
            let index = self.retired.len;
            *self.active = Some(PresencePeersRetirement::new(PresencePeersRetiredEntries::one(self.retired.entries[index].take()), self.factory.clone()));
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.created.len != 0 {
            let created = std::mem::replace(&mut *self.created, PresencePeersRetiredEntries::empty());
            *self.active = Some(PresencePeersRetirement::new(created, self.factory.clone()));
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.base_root.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(SnapshotRetirementStep::Complete)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.base_root.is_none() && self.candidate.is_none() && self.created.len == 0 && self.retired.len == 0 && self.active.is_none()
    }
}

impl<P> Drop for PresencePeersPublication<P> {
    fn drop(&mut self) {
        if !std::thread::panicking() {
            assert!(std::thread::panicking() || (self.base_root.is_none() && self.candidate.is_none() && self.created.len == 0 && self.retired.len == 0 && self.active.is_none()), "incomplete presence peer publication reached Drop without bounded disposal");
        }
    }
}

impl<P: Send + Sync + 'static> PresencePeersRetirement<P> {
    fn new(retired: PresencePeersRetiredEntries<P>, factory: Arc<dyn SnapshotRetirementFactory<P>>) -> Self {
        Self {
            root: std::mem::ManuallyDrop::new(None),
            owned_root: std::mem::ManuallyDrop::new(None),
            retired: std::mem::ManuallyDrop::new(retired),
            waiting: std::mem::ManuallyDrop::new(None),
            entry: std::mem::ManuallyDrop::new(None),
            active: std::mem::ManuallyDrop::new(None),
            factory,
            cursor: 0,
        }
    }

    pub fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, String> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(active) = self.active.as_mut() {
            return match active.close_step(maximum_items, maximum_bytes)? {
                step @ SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= maximum_items && released_bytes <= maximum_bytes => Ok(step),
                SnapshotRetirementStep::Pending { .. } => Err("presence peer snapshot disposer exceeded its exact item or byte grant".into()),
                SnapshotRetirementStep::Blocked => Ok(SnapshotRetirementStep::Blocked),
                SnapshotRetirementStep::Complete => {
                    if !active.terminal_is_empty() {
                        return Err("presence peer snapshot disposer reported Complete without its terminal-empty witness".into());
                    }
                    drop(self.active.take());
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
                }
            };
        }
        if let Some(entry) = self.entry.as_mut() {
            if let Some(scalar) = entry.actor.chars().next_back() {
                let bytes = scalar.len_utf8();
                if bytes > maximum_bytes {
                    return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
                }
                entry.actor.pop();
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: bytes });
            }
            let snapshot = entry.presence.take().ok_or_else(|| "presence peer retirement entry lost its exact snapshot authority".to_string())?;
            *self.active = Some(self.factory.retire(snapshot));
            let entry = self.entry.take().expect("empty presence peer retirement entry");
            drop(entry);
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(waiting) = self.waiting.take() {
            *self.entry = Arc::into_inner(waiting);
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.cursor < self.retired.len {
            let index = self.cursor;
            self.cursor += 1;
            if let Some(entry) = self.retired.entries[index].take() {
                *self.waiting = Some(entry);
            }
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        self.retired.len = 0;
        if let Some(root) = self.root.take() {
            return match Arc::try_unwrap(root) {
                Ok(root) => {
                    *self.owned_root = Some(root);
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
                }
                Err(root) => {
                    *self.root = Some(root);
                    Ok(SnapshotRetirementStep::Blocked)
                }
            };
        }
        if let Some(root) = self.owned_root.as_mut() {
            if root.len != 0 {
                root.len -= 1;
                *self.waiting = root.entries[root.len].take();
            } else {
                drop(self.owned_root.take());
            }
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(SnapshotRetirementStep::Complete)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.root.is_none() && self.owned_root.is_none() && self.retired.len == 0 && self.waiting.is_none() && self.entry.is_none() && self.active.is_none()
    }
}

impl<P> Drop for PresencePeersRetirement<P> {
    fn drop(&mut self) {
        if !std::thread::panicking() {
            assert!(std::thread::panicking() || (self.root.is_none() && self.owned_root.is_none() && self.retired.len == 0 && self.waiting.is_none() && self.entry.is_none() && self.active.is_none()), "incomplete presence-peer retirement reached Drop without bounded disposal");
        }
    }
}

#[path = "👥️presence/♻️retirement/🦀️.rs"]
mod presence_retirement;
pub use presence_retirement::PresenceStoreRetirement;

// 🚫️async: E1 impl of external `Default` — signature fixed outside this repo.
impl<P: Clone + Default, Mutation: self::Mutation<P>> Default for PresenceStore<P, Mutation> {
    fn default() -> Self {
        Self::new(P::default())
    }
}

impl<P: Clone, Mutation: self::Mutation<P>> PresenceStore<P, Mutation> {
    /// 🏗️ A roster holding only this actor's own initial presence.
    // 🚫️async: E1 pure constructor, consumed by `Default::default()` — see R9.
    pub fn new(local: P) -> Self {
        Self {
            local: std::mem::ManuallyDrop::new(Arc::new(local)),
            peers: std::mem::ManuallyDrop::new(Arc::new(PresencePeersRoot::empty())),
            peer_retirement_factory: None,
            local_retirement_factory: None,
            local_reads: std::mem::ManuallyDrop::new(Arc::new(SnapshotReadLeaseRegistry::new())),
            active_returned_local: std::mem::ManuallyDrop::new(None),
            generation: 0,
            close_started: false,
            _mutation: PhantomData,
        }
    }

    /// 👤️ This actor's own presence — what gets broadcast.
    pub fn local(&self) -> &P {
        self.local.as_ref()
    }

    /// 🧵️ Captures the event-maintained local presence root without cloning its payload.
    pub fn local_read(&self) -> Result<SnapshotRead<P>, String>
    where
        P: Send + Sync + 'static,
    {
        if self.close_started || self.local_retirement_factory.is_none() {
            return Err("presence local read requires a live exact local retirement owner".into());
        }
        let owner = Arc::clone(&self.local);
        let lease = self.local_reads.try_issue(owner.clone()).map_err(|_| "presence local read registry is busy or exhausted".to_string())?;
        Ok(SnapshotRead::new(owner, lease))
    }

    pub fn install_local_retirement_factory(&mut self, factory: Arc<dyn SnapshotRetirementFactory<P>>) -> Result<(), String> {
        if self.close_started || self.local_retirement_factory.is_some() {
            return Err("presence local retirement factory is already installed".into());
        }
        self.local_retirement_factory = Some(factory);
        Ok(())
    }

    pub fn maintenance_local_reads_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, String>
    where
        P: Send + Sync + 'static,
    {
        presence_retirement::advance_returned_local(&self.local_reads, &mut self.active_returned_local, self.local_retirement_factory.as_ref(), maximum_items, maximum_bytes)
    }

    pub fn local_read_maintenance_is_idle(&self) -> bool {
        self.active_returned_local.is_none() && !self.local_reads.has_returned()
    }

    /// ✍️ Applies local presence operations atomically, bumping `generation` after the full batch.
    pub async fn apply(&mut self, mutations: &[Mutation]) -> crate::os_spr::MutationApplyResult<()>
    where
        P: Send + Sync + 'static,
    {
        if self.close_started {
            return Err(crate::os_spr::MutationApplyError::new("presence.store.closed", "presence store no longer admits local mutations"));
        }
        if mutations.is_empty() {
            return Ok(());
        }
        let previous = self.local_read().map_err(|reason| crate::os_spr::MutationApplyError::new("presence.local.owner", reason))?;
        let mut candidate = self.local.as_ref().clone();
        for mutation in mutations {
            candidate = mutation.diff(&candidate).diff().apply(&candidate)?;
        }
        if !mutations.is_empty() {
            *self.local = Arc::new(candidate);
            self.generation = self.generation.wrapping_add(1);
        }
        previous.return_to_registry();
        Ok(())
    }

    pub fn begin_publish_one(
        &self,
        operation: semio_framework_job::OperationId,
        expected_generation: u64,
        mutation: Mutation,
        factory: Option<&dyn ArtifactEphemeralOneItemPreparationFactory<P, Mutation>>,
        root_retirement_factory: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    ) -> Result<ArtifactEphemeralOneItemPublication<P, Mutation>, ArtifactEphemeralOneItemAdmissionRejected<Mutation>>
    where
        P: Send + Sync + 'static,
    {
        let reject = |reason: String, mutation: Mutation| ArtifactEphemeralOneItemAdmissionRejected { reason, mutation };
        if self.close_started {
            return Err(reject("presence store no longer admits local publication".into(), mutation));
        }
        if self.generation != expected_generation {
            return Err(reject("presence publication generation is stale".into(), mutation));
        }
        let Some(factory) = factory else {
            return Err(reject("presence publication requires an explicit app-owned retained preparation factory".into(), mutation));
        };
        let Some(root_retirement_factory) = root_retirement_factory else {
            return Err(reject("presence publication requires an explicit local-root retirement factory".into(), mutation));
        };
        let footprint = match factory.preflight(&mutation) {
            Ok(footprint) if footprint.is_admissible() => footprint,
            Ok(_) => return Err(reject("presence publication footprint exceeds its fixed item or byte capacity".into(), mutation)),
            Err(reason) => return Err(reject(reason, mutation)),
        };
        if !self.local_retirement_factory.as_ref().is_some_and(|installed| Arc::ptr_eq(installed, &root_retirement_factory)) {
            return Err(reject("presence publication requires its exact installed local-root retirement factory".into(), mutation));
        }
        let base = match self.local_read() {
            Ok(read) => ArtifactEphemeralBaseRead(ArtifactEphemeralBaseOwner::Presence(read)),
            Err(reason) => return Err(reject(reason, mutation)),
        };
        let request = ArtifactEphemeralOneItemPreparationRequest { operation, generation: semio_framework_job::Generation(expected_generation), base, mutation };
        let preparation = match factory.begin(request) {
            Ok(preparation) => preparation,
            Err(request) => return Err(reject("presence preparation factory rejected its exact owner bundle".into(), request.mutation)),
        };
        Ok(ArtifactEphemeralOneItemPublication {
            operation,
            expected_generation,
            footprint,
            preparation: Some(preparation),
            displaced_root_retirement: None,
            root_retirement_factory: Some(root_retirement_factory),
            returned_read_registry: None,
            returned_read_retirement: None,
            owned_retirement_factory: None,
            receipt: None,
            attempts: 0,
            published: false,
            cancel_requested: false,
            close_started: false,
            fault: None,
            phase: ArtifactStoreOneItemPublicationPhase::Preparing,
        })
    }

    pub fn advance_publish_one(&mut self, publication: &mut ArtifactEphemeralOneItemPublication<P, Mutation>, grant: ArtifactStoreOneItemGrant) -> Result<ArtifactStoreOneItemAdvance, String> {
        if publication.phase == ArtifactStoreOneItemPublicationPhase::Complete {
            return Ok(ArtifactStoreOneItemAdvance::Complete);
        }
        if publication.phase == ArtifactStoreOneItemPublicationPhase::Closing {
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        if publication.phase == ArtifactStoreOneItemPublicationPhase::AwaitingAck {
            return Ok(ArtifactStoreOneItemAdvance::AwaitingAck(publication.receipt.expect("presence publication awaiting ACK retains its receipt")));
        }
        if self.close_started {
            publication.begin_close();
            return Err("presence store closed before publication".into());
        }
        if publication.cancel_requested {
            publication.begin_close();
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        if self.generation != publication.expected_generation {
            publication.fault = Some("presence publication became stale before commit".into());
            publication.phase = ArtifactStoreOneItemPublicationPhase::Fault;
            publication.begin_close();
            return Err("presence publication became stale before commit".into());
        }
        if !grant.permits_one() {
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        match publication.phase {
            ArtifactStoreOneItemPublicationPhase::Preparing => {
                match publication.advance_preparation(grant)? {
                    ArtifactStoreOneItemPreparationStep::Progress(checkpoint) => Ok(ArtifactStoreOneItemAdvance::Progress(checkpoint)),
                    ArtifactStoreOneItemPreparationStep::Prepared(checkpoint) => {
                        publication.phase = ArtifactStoreOneItemPublicationPhase::PreparingCursor;
                        Ok(ArtifactStoreOneItemAdvance::Progress(checkpoint))
                    }
                    ArtifactStoreOneItemPreparationStep::Blocked => Ok(ArtifactStoreOneItemAdvance::Blocked),
                }
            }
            ArtifactStoreOneItemPublicationPhase::PreparingCursor => {
                if publication.preparation.as_ref().and_then(|owner| owner.prepared()).is_none() {
                    return Err("presence prepared root is absent".into());
                }
                publication.phase = ArtifactStoreOneItemPublicationPhase::PreflightingCommit;
                Ok(ArtifactStoreOneItemAdvance::Progress(publication.progress()))
            }
            ArtifactStoreOneItemPublicationPhase::PreflightingCommit => {
                if self.generation == u64::MAX || publication.footprint.work_items == 0 {
                    return Err("presence publication fixed commit authority is exhausted".into());
                }
                publication.phase = ArtifactStoreOneItemPublicationPhase::Publishing;
                Ok(ArtifactStoreOneItemAdvance::Progress(publication.progress()))
            }
            ArtifactStoreOneItemPublicationPhase::Publishing => {
                let prepared = publication.preparation.as_mut().and_then(|owner| owner.take_prepared()).ok_or_else(|| "presence publication lost its prepared root".to_string())?;
                let generation_before = self.generation;
                let previous = std::mem::replace(&mut *self.local, prepared.next_root);
                let retirement_factory = publication.root_retirement_factory.as_ref().ok_or_else(|| "presence publication lost its local-root retirement factory".to_string())?;
                publication.displaced_root_retirement = Some(retirement_factory.retire(previous));
                self.generation += 1;
                let receipt = LaneItemReceipt { generation_before, generation_after: self.generation };
                publication.expected_generation = self.generation;
                publication.receipt = Some(receipt);
                publication.published = true;
                publication.phase = ArtifactStoreOneItemPublicationPhase::AwaitingAck;
                Ok(ArtifactStoreOneItemAdvance::Published(receipt))
            }
            ArtifactStoreOneItemPublicationPhase::Fault => Err(publication.fault.clone().unwrap_or_else(|| "presence publication faulted".into())),
            ArtifactStoreOneItemPublicationPhase::AwaitingAck | ArtifactStoreOneItemPublicationPhase::Closing | ArtifactStoreOneItemPublicationPhase::Complete => unreachable!("handled presence publication control phase"),
        }
    }

    pub fn cancel_publish_one(&mut self, publication: &mut ArtifactEphemeralOneItemPublication<P, Mutation>) -> bool {
        if matches!(publication.phase, ArtifactStoreOneItemPublicationPhase::Complete | ArtifactStoreOneItemPublicationPhase::Closing) {
            return false;
        }
        publication.cancel_requested = true;
        publication.begin_close();
        true
    }

    /// 🎯️ Applies one retained publication item against an exact generation and returns its
    /// per-lane receipt. A stale item is rejected before its mutation is inspected.
    pub fn apply_one(&mut self, expected_generation: u64, mutation: Mutation) -> Result<LaneItemReceipt, (String, Mutation)>
    where
        P: Send + Sync + 'static,
    {
        if self.close_started {
            return Err(("presence store no longer admits local mutations".into(), mutation));
        }
        if self.generation != expected_generation {
            return Err(("presence publication generation is stale".into(), mutation));
        }
        let before = self.generation;
        let previous = match self.local_read() {
            Ok(previous) => previous,
            Err(reason) => return Err((reason, mutation)),
        };
        let candidate = match mutation.diff(self.local.as_ref()).diff().apply(self.local.as_ref()) {
            Ok(candidate) => candidate,
            Err(error) => return Err((error.to_string(), mutation)),
        };
        *self.local = Arc::new(candidate);
        self.generation = self.generation.wrapping_add(1);
        previous.return_to_registry();
        Ok(LaneItemReceipt { generation_before: before, generation_after: self.generation })
    }

    pub fn peers_root(&self) -> Arc<PresencePeersRoot<P>> {
        Arc::clone(&self.peers)
    }

    pub fn install_peer_retirement_factory(&mut self, factory: Arc<dyn SnapshotRetirementFactory<P>>) -> Result<(), String> {
        if self.close_started || self.peer_retirement_factory.is_some() {
            return Err("presence peer retirement factory is already installed".into());
        }
        self.peer_retirement_factory = Some(factory);
        Ok(())
    }

    pub fn peer_retirement_available(&self) -> bool {
        self.peer_retirement_factory.is_some()
    }

    pub fn begin_peer_retirement(&self, retired: PresencePeersRetiredEntries<P>) -> Result<PresencePeersRetirement<P>, PresencePeersRetiredEntries<P>>
    where
        P: Send + Sync + 'static,
    {
        let Some(factory) = self.peer_retirement_factory.as_ref() else { return Err(retired) };
        Ok(PresencePeersRetirement::new(retired, factory.clone()))
    }

    pub fn begin_peer_publication(&self) -> Result<PresencePeersPublication<P>, String>
    where
        P: Send + Sync + 'static,
    {
        if self.close_started {
            return Err("presence store no longer admits peer publication".into());
        }
        let factory = self.peer_retirement_factory.as_ref().ok_or_else(|| "presence peer publication has no exact bounded snapshot retirement factory".to_string())?;
        Ok(PresencePeersPublication::new(&self.peers, factory.clone()))
    }

    pub fn publish_peer_commit(&mut self, commit: PresencePeersCommit<P>) -> Result<Option<PresencePeersRetirement<P>>, PresencePeersCommit<P>>
    where
        P: Send + Sync + 'static,
    {
        if self.close_started || !Arc::ptr_eq(&self.peers, &commit.base_root) || !self.peer_retirement_factory.as_ref().is_some_and(|factory| Arc::ptr_eq(factory, &commit.factory)) {
            return Err(commit);
        }
        let previous = std::mem::replace(&mut *self.peers, commit.root);
        let mut retirement = commit.retirement.unwrap_or_else(|| PresencePeersRetirement::new(PresencePeersRetiredEntries::empty(), commit.factory));
        *retirement.root = Some(previous);
        drop(commit.base_root);
        Ok(Some(retirement))
    }

    /// 🔢️ Bumps on every local change; never on adopting a remote peer (that needs no rebroadcast).
    pub async fn generation(&self) -> u64 {
        self.generation
    }

    /// 🪪️ Reads the event-maintained generation at an already-owned operation boundary.
    pub fn generation_now(&self) -> u64 {
        self.generation
    }
}

/// @emoji 🫧️ The TRANSIENT lane's store: ephemeral LOCAL-ONLY UI state.
///
/// 🎯️ Presence minus the roster. Nothing here is ever shared, persisted, packed, checkpointed or
/// undone — it is exactly the state that used to hide in plugin `thread_local!`s and untyped shell
/// fields, given a typed home so it can be reached only through `Emit`/`Lanes` like every other
/// lane. If a value must survive a reload it belongs in `config`; if a peer must see it, in
/// `presence`; if it is document content, in the artifact (or its draft).
pub struct TransientStore<P, Mutation> {
    current: Arc<P>,
    reads: Arc<SnapshotReadLeaseRegistry>,
    active_returned_read: Option<Box<dyn ErasedSnapshotRetirement>>,
    generation: u64,
    _mutation: PhantomData<fn() -> Mutation>,
}

// 🚫️async: E1 impl of external `Default` — signature fixed outside this repo.
impl<P: Clone + Default, Mutation: self::Mutation<P>> Default for TransientStore<P, Mutation> {
    fn default() -> Self {
        Self::new(P::default())
    }
}

impl<P: Clone, Mutation: self::Mutation<P>> TransientStore<P, Mutation> {
    // 🚫️async: E1 pure constructor, consumed by `Default::default()` — see R9.
    pub fn new(current: P) -> Self {
        Self { current: Arc::new(current), reads: Arc::new(SnapshotReadLeaseRegistry::new()), active_returned_read: None, generation: 0, _mutation: PhantomData }
    }

    pub async fn current(&self) -> &P {
        self.current.as_ref()
    }

    /// 🧵️ Captures the event-maintained transient root without cloning its payload.
    pub fn current_root(&self) -> Arc<P> {
        self.current.clone()
    }

    /// 🧵️ Captures one tracked transient root capability for retained work.
    pub fn current_read(&self) -> Result<SnapshotRead<P>, String>
    where
        P: Send + Sync + 'static,
    {
        let owner = Arc::clone(&self.current);
        let lease = self.reads.try_issue(owner.clone()).map_err(|_| "transient read registry is busy or exhausted".to_string())?;
        Ok(SnapshotRead::new(owner, lease))
    }

    /// 🧰️ Captures the same tracked capability across a heterogeneous owner registry.
    pub fn current_read_erased(&self) -> Result<ErasedSnapshotRead, String>
    where
        P: Send + Sync + 'static,
    {
        let owner = Arc::clone(&self.current);
        let lease = self.reads.try_issue(owner.clone()).map_err(|_| "transient read registry is busy or exhausted".to_string())?;
        Ok(ErasedSnapshotRead::new(owner, lease))
    }

    /// 🧹️ Advances one returned read through its exact owned-value retirement authority.
    pub fn maintenance_returned_reads_step(&mut self, factory: &Arc<dyn ArtifactOwnedValueRetirementFactory<P>>, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, String>
    where
        P: Send + Sync + 'static,
    {
        advance_returned_snapshot_read(&self.reads, &mut self.active_returned_read, factory, maximum_items, maximum_bytes)
    }

    pub fn returned_reads_terminal_is_empty(&self) -> bool {
        self.active_returned_read.is_none() && self.reads.terminal_is_empty()
    }

    pub fn current_weak(&self) -> std::sync::Weak<P> {
        Arc::downgrade(&self.current)
    }

    pub fn current_matches(&self, root: &std::sync::Weak<P>) -> bool {
        root.upgrade().is_some_and(|root| Arc::ptr_eq(&root, &self.current))
    }

    /// ✍️ Applies transient operations atomically, without history.
    pub async fn apply(&mut self, mutations: &[Mutation]) -> crate::os_spr::MutationApplyResult<()> {
        let mut candidate = self.current.as_ref().clone();
        for mutation in mutations {
            candidate = mutation.diff(&candidate).diff().apply(&candidate)?;
        }
        if !mutations.is_empty() {
            self.current = Arc::new(candidate);
            self.generation = self.generation.wrapping_add(1);
        }
        Ok(())
    }

    pub fn begin_publish_one(
        &self,
        operation: semio_framework_job::OperationId,
        expected_generation: u64,
        mutation: Mutation,
        factory: Option<&dyn ArtifactEphemeralOneItemPreparationFactory<P, Mutation>>,
        root_retirement_factory: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    ) -> Result<ArtifactEphemeralOneItemPublication<P, Mutation>, ArtifactEphemeralOneItemAdmissionRejected<Mutation>> {
        let reject = |reason: String, mutation: Mutation| ArtifactEphemeralOneItemAdmissionRejected { reason, mutation };
        if self.generation != expected_generation {
            return Err(reject("transient publication generation is stale".into(), mutation));
        }
        let Some(factory) = factory else {
            return Err(reject("transient publication requires an explicit app-owned retained preparation factory".into(), mutation));
        };
        let Some(root_retirement_factory) = root_retirement_factory else {
            return Err(reject("transient publication requires an explicit local-root retirement factory".into(), mutation));
        };
        let footprint = match factory.preflight(&mutation) {
            Ok(footprint) if footprint.is_admissible() => footprint,
            Ok(_) => return Err(reject("transient publication footprint exceeds its fixed item or byte capacity".into(), mutation)),
            Err(reason) => return Err(reject(reason, mutation)),
        };
        let request =
            ArtifactEphemeralOneItemPreparationRequest { operation, generation: semio_framework_job::Generation(expected_generation), base: ArtifactEphemeralBaseRead(ArtifactEphemeralBaseOwner::Transient(Arc::clone(&self.current))), mutation };
        let preparation = match factory.begin(request) {
            Ok(preparation) => preparation,
            Err(request) => return Err(reject("transient preparation factory rejected its exact owner bundle".into(), request.mutation)),
        };
        Ok(ArtifactEphemeralOneItemPublication {
            operation,
            expected_generation,
            footprint,
            preparation: Some(preparation),
            displaced_root_retirement: None,
            root_retirement_factory: Some(root_retirement_factory),
            returned_read_registry: None,
            returned_read_retirement: None,
            owned_retirement_factory: None,
            receipt: None,
            attempts: 0,
            published: false,
            cancel_requested: false,
            close_started: false,
            fault: None,
            phase: ArtifactStoreOneItemPublicationPhase::Preparing,
        })
    }

    /// 📬️ Begins one transient publication from a tracked base read. Displaced roots use
    /// unique-or-release retirement so a still-live tool read cannot create a close cycle.
    pub fn begin_publish_one_leased(
        &self,
        operation: semio_framework_job::OperationId,
        expected_generation: u64,
        mutation: Mutation,
        factory: &dyn ArtifactEphemeralOneItemPreparationFactory<P, Mutation>,
        owned_retirement_factory: Arc<dyn ArtifactOwnedValueRetirementFactory<P>>,
    ) -> Result<ArtifactEphemeralOneItemPublication<P, Mutation>, ArtifactEphemeralOneItemAdmissionRejected<Mutation>>
    where
        P: Send + Sync + 'static,
    {
        let reject = |reason: String, mutation: Mutation| ArtifactEphemeralOneItemAdmissionRejected { reason, mutation };
        if self.generation != expected_generation {
            return Err(reject("transient publication generation is stale".into(), mutation));
        }
        let footprint = match factory.preflight(&mutation) {
            Ok(footprint) if footprint.is_admissible() => footprint,
            Ok(_) => return Err(reject("transient publication footprint exceeds its fixed item or byte capacity".into(), mutation)),
            Err(reason) => return Err(reject(reason, mutation)),
        };
        let base = match self.current_read() {
            Ok(read) => ArtifactEphemeralBaseRead(ArtifactEphemeralBaseOwner::TransientRead(read)),
            Err(reason) => return Err(reject(reason, mutation)),
        };
        let request = ArtifactEphemeralOneItemPreparationRequest { operation, generation: semio_framework_job::Generation(expected_generation), base, mutation };
        let preparation = match factory.begin(request) {
            Ok(preparation) => preparation,
            Err(request) => return Err(reject("transient preparation factory rejected its exact owner bundle".into(), request.mutation)),
        };
        Ok(ArtifactEphemeralOneItemPublication {
            operation,
            expected_generation,
            footprint,
            preparation: Some(preparation),
            displaced_root_retirement: None,
            root_retirement_factory: None,
            returned_read_registry: Some(self.reads.clone()),
            returned_read_retirement: None,
            owned_retirement_factory: Some(owned_retirement_factory),
            receipt: None,
            attempts: 0,
            published: false,
            cancel_requested: false,
            close_started: false,
            fault: None,
            phase: ArtifactStoreOneItemPublicationPhase::Preparing,
        })
    }

    pub fn advance_publish_one(&mut self, publication: &mut ArtifactEphemeralOneItemPublication<P, Mutation>, grant: ArtifactStoreOneItemGrant) -> Result<ArtifactStoreOneItemAdvance, String>
    where
        P: Send + Sync + 'static,
    {
        if publication.phase == ArtifactStoreOneItemPublicationPhase::Complete {
            return Ok(ArtifactStoreOneItemAdvance::Complete);
        }
        if publication.phase == ArtifactStoreOneItemPublicationPhase::Closing {
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        if publication.phase == ArtifactStoreOneItemPublicationPhase::AwaitingAck {
            return Ok(ArtifactStoreOneItemAdvance::AwaitingAck(publication.receipt.expect("transient publication awaiting ACK retains its receipt")));
        }
        if publication.cancel_requested {
            publication.begin_close();
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        if self.generation != publication.expected_generation {
            publication.fault = Some("transient publication became stale before commit".into());
            publication.phase = ArtifactStoreOneItemPublicationPhase::Fault;
            publication.begin_close();
            return Err("transient publication became stale before commit".into());
        }
        if !grant.permits_one() {
            return Ok(ArtifactStoreOneItemAdvance::Blocked);
        }
        match publication.phase {
            ArtifactStoreOneItemPublicationPhase::Preparing => {
                match publication.advance_preparation(grant)? {
                    ArtifactStoreOneItemPreparationStep::Progress(checkpoint) => Ok(ArtifactStoreOneItemAdvance::Progress(checkpoint)),
                    ArtifactStoreOneItemPreparationStep::Prepared(checkpoint) => {
                        publication.phase = ArtifactStoreOneItemPublicationPhase::PreparingCursor;
                        Ok(ArtifactStoreOneItemAdvance::Progress(checkpoint))
                    }
                    ArtifactStoreOneItemPreparationStep::Blocked => Ok(ArtifactStoreOneItemAdvance::Blocked),
                }
            }
            ArtifactStoreOneItemPublicationPhase::PreparingCursor => {
                if publication.preparation.as_ref().and_then(|owner| owner.prepared()).is_none() {
                    return Err("transient prepared root is absent".into());
                }
                publication.phase = ArtifactStoreOneItemPublicationPhase::PreflightingCommit;
                Ok(ArtifactStoreOneItemAdvance::Progress(publication.progress()))
            }
            ArtifactStoreOneItemPublicationPhase::PreflightingCommit => {
                if self.generation == u64::MAX || publication.footprint.work_items == 0 {
                    return Err("transient publication fixed commit authority is exhausted".into());
                }
                publication.phase = ArtifactStoreOneItemPublicationPhase::Publishing;
                Ok(ArtifactStoreOneItemAdvance::Progress(publication.progress()))
            }
            ArtifactStoreOneItemPublicationPhase::Publishing => {
                let prepared = publication.preparation.as_mut().and_then(|owner| owner.take_prepared()).ok_or_else(|| "transient publication lost its prepared root".to_string())?;
                let generation_before = self.generation;
                let previous = std::mem::replace(&mut self.current, prepared.next_root);
                publication.displaced_root_retirement = Some(if let Some(factory) = publication.owned_retirement_factory.as_ref() {
                    Box::new(ReturnedSnapshotReadRetirement::new(previous, factory.clone()))
                } else {
                    publication.root_retirement_factory.as_ref().ok_or_else(|| "transient publication lost its local-root retirement factory".to_string())?.retire(previous)
                });
                self.generation += 1;
                let receipt = LaneItemReceipt { generation_before, generation_after: self.generation };
                publication.expected_generation = self.generation;
                publication.receipt = Some(receipt);
                publication.published = true;
                publication.phase = ArtifactStoreOneItemPublicationPhase::AwaitingAck;
                Ok(ArtifactStoreOneItemAdvance::Published(receipt))
            }
            ArtifactStoreOneItemPublicationPhase::Fault => Err(publication.fault.clone().unwrap_or_else(|| "transient publication faulted".into())),
            ArtifactStoreOneItemPublicationPhase::AwaitingAck | ArtifactStoreOneItemPublicationPhase::Closing | ArtifactStoreOneItemPublicationPhase::Complete => unreachable!("handled transient publication control phase"),
        }
    }

    pub fn cancel_publish_one(&mut self, publication: &mut ArtifactEphemeralOneItemPublication<P, Mutation>) -> bool {
        if matches!(publication.phase, ArtifactStoreOneItemPublicationPhase::Complete | ArtifactStoreOneItemPublicationPhase::Closing) {
            return false;
        }
        publication.cancel_requested = true;
        publication.begin_close();
        true
    }

    /// 🎯️ Applies one retained local-only item against an exact live generation.
    pub fn apply_one(&mut self, expected_generation: u64, mutation: Mutation) -> Result<LaneItemReceipt, (String, Mutation)> {
        if self.generation != expected_generation {
            return Err(("transient publication generation is stale".into(), mutation));
        }
        let before = self.generation;
        let candidate = match mutation.diff(self.current.as_ref()).diff().apply(self.current.as_ref()) {
            Ok(candidate) => candidate,
            Err(error) => return Err((error.to_string(), mutation)),
        };
        self.current = Arc::new(candidate);
        self.generation = self.generation.wrapping_add(1);
        Ok(LaneItemReceipt { generation_before: before, generation_after: self.generation })
    }

    /// 🔄️ Discards everything — what a host does when a view closes.
    pub async fn reset(&mut self, current: P) {
        self.current = Arc::new(current);
        self.generation = self.generation.wrapping_add(1);
    }

    /// 🔢️ Bumps on every change, so a renderer can skip untouched frames.
    pub async fn generation(&self) -> u64 {
        self.generation
    }

    /// 🪪️ Reads the event-maintained transient generation without suspension.
    pub fn generation_now(&self) -> u64 {
        self.generation
    }

    /// ♻️ Detaches this store's exact root/read registry and installs a fresh terminal root.
    pub fn begin_retirement(&mut self, terminal: P, factory: Arc<dyn ArtifactOwnedValueRetirementFactory<P>>) -> TransientStoreRetirement<P>
    where
        P: Send + Sync + 'static,
    {
        let next_generation = self.generation.wrapping_add(1);
        let displaced = std::mem::replace(self, Self::new(terminal));
        self.generation = next_generation;
        TransientStoreRetirement::new(displaced, factory)
    }
}

/// ♻️ Detached transient root plus every returned/live tracked read.
pub struct TransientStoreRetirement<P> {
    root: std::mem::ManuallyDrop<Option<Arc<P>>>,
    reads: std::mem::ManuallyDrop<Option<Arc<SnapshotReadLeaseRegistry>>>,
    active_returned: std::mem::ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,
    active_root: std::mem::ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,
    factory: Option<Arc<dyn ArtifactOwnedValueRetirementFactory<P>>>,
}

impl<P> TransientStoreRetirement<P> {
    fn new<Mutation>(store: TransientStore<P, Mutation>, factory: Arc<dyn ArtifactOwnedValueRetirementFactory<P>>) -> Self {
        let store = std::mem::ManuallyDrop::new(store);
        Self {
            root: std::mem::ManuallyDrop::new(Some(unsafe { std::ptr::read(&store.current) })),
            reads: std::mem::ManuallyDrop::new(Some(unsafe { std::ptr::read(&store.reads) })),
            active_returned: std::mem::ManuallyDrop::new(unsafe { std::ptr::read(&store.active_returned_read) }),
            active_root: std::mem::ManuallyDrop::new(None),
            factory: Some(factory),
        }
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.root.is_none() && self.reads.is_none() && self.active_returned.is_none() && self.active_root.is_none() && self.factory.is_none()
    }
}

impl<P: Send + Sync + 'static> TransientStoreRetirement<P> {
    pub fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<SnapshotRetirementStep, String> {
        if maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(reads) = self.reads.as_ref() {
            if self.active_returned.is_some() || reads.has_returned() {
                return advance_returned_snapshot_read(reads, &mut self.active_returned, self.factory.as_ref().ok_or_else(|| "transient retirement lost its owned factory".to_string())?, 1, maximum_bytes);
            }
        }
        if let Some(active) = self.active_root.as_mut() {
            return match active.close_step(1, maximum_bytes)? {
                SnapshotRetirementStep::Complete if active.terminal_is_empty() => {
                    drop(self.active_root.take());
                    Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 })
                }
                SnapshotRetirementStep::Complete => Err("transient root completed without its exact empty witness".into()),
                SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items > 1 || released_bytes > maximum_bytes => Err("transient root exceeded its exact grant".into()),
                step => Ok(step),
            };
        }
        if let Some(root) = self.root.take() {
            *self.active_root = Some(Box::new(ReturnedSnapshotReadRetirement::new(root, self.factory.as_ref().ok_or_else(|| "transient retirement lost its owned factory".to_string())?.clone())));
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.reads.as_ref().is_some_and(|reads| !reads.terminal_is_empty()) {
            return Ok(SnapshotRetirementStep::Blocked);
        }
        if self.reads.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.factory.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(SnapshotRetirementStep::Complete)
    }
}

impl<P> Drop for TransientStoreRetirement<P> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "transient store retirement reached Drop before terminal-empty ownership");
        unsafe {
            std::mem::ManuallyDrop::drop(&mut self.root);
            std::mem::ManuallyDrop::drop(&mut self.reads);
            std::mem::ManuallyDrop::drop(&mut self.active_returned);
            std::mem::ManuallyDrop::drop(&mut self.active_root);
        }
    }
}

//#region 🔖️InteractionStore
/// @emoji 🕹️ Ephemeral LOCAL-ONLY lane for the framework interaction mechanism's hover half — the
/// `PresenceStore`/`TransientStore` sibling for `InteractionState.hover`.
///
/// 🎯️ Only hover lives here. Selection + `active_mode`/`active_granularity` are
/// **persisted-local** (`InteractionState`'s other three fields) and already flow through the
/// ordinary `ConfigStore` (`ArtifactStore<Config, ConfigMutation>`) via `ArtifactCommand::
/// ApplyInLane { lane: HistoryLane::Interaction, .. }` — no new store type needed for that half,
/// it is the ENTIRE point of the `HistoryLane` mechanism above. Hover must never take that path
/// (never persisted, never in `Edit`/`Change` history), so it gets this dedicated ephemeral
/// sibling instead, shaped exactly like `TransientStore` (single local value, no peer roster —
/// peers' hover arrives over the wire as `PresencePeer.interaction`, not through this store).
///
/// `S`/`Mutation` are supplied by the caller (mirrors `PresenceStore<A::Presence,
/// A::PresenceMutation>` in `VcsArtifactApp`): this crate has no dependency edge to the
/// `semio-framework` crate that owns `InteractionState`/`DomainHover` (that crate depends on
/// THIS one, for its `spr`/`dsl`/`pack` types — the reverse edge would cycle), so `S` stays
/// generic here and gets instantiated with the app's concrete hover-shaped type one layer up,
/// where that dependency edge actually exists.
#[derive(Clone, Debug)]
pub struct InteractionStore<S, Mutation> {
    hover: S,
    generation: u64,
    _mutation: PhantomData<fn() -> Mutation>,
}

// 🚫️async: E1 impl of external `Default` — signature fixed outside this repo.
impl<S: Clone + Default, Mutation: self::Mutation<S>> Default for InteractionStore<S, Mutation> {
    fn default() -> Self {
        Self::new(S::default())
    }
}

impl<S: Clone, Mutation: self::Mutation<S>> InteractionStore<S, Mutation> {
    /// 🏗️ Starts with this actor's own initial hover state (typically empty).
    // 🚫️async: E1 pure constructor, consumed by `Default::default()` — see R9.
    pub fn new(hover: S) -> Self {
        Self { hover, generation: 0, _mutation: PhantomData }
    }

    /// 👁️ This actor's own hover — what the presence heartbeat mirrors onto `PresenceDomain.hovered`.
    pub async fn hover(&self) -> &S {
        &self.hover
    }

    /// ✍️ Applies hover updates atomically. The caller's `Mutation` impl is expected to route
    /// through the framework's `next_hover` pure fn before landing here.
    pub async fn apply(&mut self, mutations: &[Mutation]) -> crate::os_spr::MutationApplyResult<()> {
        let mut candidate = self.hover.clone();
        for mutation in mutations {
            candidate = mutation.diff(&candidate).diff().apply(&candidate)?;
        }
        if !mutations.is_empty() {
            self.hover = candidate;
            self.generation = self.generation.wrapping_add(1);
        }
        Ok(())
    }

    /// 🔄️ Discards hover — a host clears this when a view/window closes (nothing left to hover).
    pub async fn reset(&mut self, hover: S) {
        self.hover = hover;
        self.generation = self.generation.wrapping_add(1);
    }

    /// 🔢️ Bumps on every local hover change; drives the same broadcast-coalescing signal as
    /// `PresenceStore::generation`.
    pub async fn generation(&self) -> u64 {
        self.generation
    }
}
